package usecase

import (
	"context"
	"fmt"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/event"
	"github.com/alexandre/wagering/internal/domain/wager"
	"time"
)

func (u *SubmitTransaction) meta(t *wager.Transaction) event.Meta {
	s := t.Snapshot()
	cor := s.CorrelationID
	if cor == "" {
		cor = s.ID
	}
	return event.Meta{EventID: u.ids.NewID(), AggregateID: s.WalletID, CorrelationID: cor, CausationID: s.CausationID, OccurredAt: u.clock.Now()}
}
func addEvent(ctx context.Context, tx port.Tx, e event.Outgoing, err error) error {
	if err != nil {
		return err
	}
	return tx.Outbox().Add(ctx, e)
}
func (u *SubmitTransaction) reject(ctx context.Context, tx port.Tx, t *wager.Transaction, code wager.FailureCode) error {
	if err := t.Reject(code, u.clock.Now()); err != nil {
		return err
	}
	if err := tx.Transactions().Update(ctx, t); err != nil {
		return err
	}
	s := t.Snapshot()
	e, err := event.NewRejected(u.meta(t), event.RejectedData{TransactionID: s.ID, Kind: string(s.Kind), WalletID: s.WalletID, ProviderID: s.ProviderID, ExternalTransactionID: s.ExternalID, FailureCode: string(code)}).ToOutgoing()
	return addEvent(ctx, tx, e, err)
}
func (u *SubmitTransaction) processedEvent(ctx context.Context, tx port.Tx, t *wager.Transaction) error {
	s := t.Snapshot()
	e, err := event.NewProcessed(u.meta(t), event.ProcessedData{TransactionID: s.ID, Kind: string(s.Kind), WalletID: s.WalletID, PlayerID: s.PlayerID, ProviderID: s.ProviderID, ExternalTransactionID: s.ExternalID, RoundID: s.RoundID, Money: event.ToMoneyDTO(s.Amount)}).ToOutgoing()
	return addEvent(ctx, tx, e, err)
}
func (u *SubmitTransaction) balanceEvent(ctx context.Context, tx port.Tx, t *wager.Transaction, entry wager.LedgerEntry, version int64) error {
	e, err := event.NewBalanceChanged(u.meta(t), event.BalanceChangedData{WalletID: t.WalletID(), TransactionID: t.ID(), Direction: string(entry.Direction()), Money: event.ToMoneyDTO(entry.Amount()), BalanceBefore: event.ToMoneyDTO(entry.BalanceBefore()), BalanceAfter: event.ToMoneyDTO(entry.BalanceAfter()), WalletVersion: version}).ToOutgoing()
	return addEvent(ctx, tx, e, err)
}
func (u *SubmitTransaction) waitReference(ctx context.Context, tx port.Tx, t *wager.Transaction) error {
	s := t.Snapshot()
	now := u.clock.Now()
	if s.Attempts >= MaxReferenceAttempts || t.ReferenceExpired(now) {
		return u.reject(ctx, tx, t, wager.FailReferenceNotFound)
	}
	if err := t.MarkPendingReference(now, now.Add(Backoff(s.Attempts)), 10*time.Minute); err != nil {
		return err
	}
	if err := tx.Transactions().Update(ctx, t); err != nil {
		return err
	}
	if s.Status == wager.StatusPendingReference {
		return nil
	}
	s = t.Snapshot()
	e, err := event.NewPendingReference(u.meta(t), event.PendingReferenceData{TransactionID: s.ID, ProviderID: s.ProviderID, ExternalTransactionID: s.ExternalID, ReferenceExternalTransactionID: s.ReferenceExternalID, NextAttemptAt: *s.NextAttemptAt, ExpiresAt: *s.ExpiresAt}).ToOutgoing()
	return addEvent(ctx, tx, e, err)
}
func (u *SubmitTransaction) process(ctx context.Context, tx port.Tx, t *wager.Transaction) error {
	accounting, ok := tx.(port.AccountingTransaction)
	if !ok {
		return fmt.Errorf("unit of work lacks paired accounting storage")
	}
	facts, err := accounting.LoadAccounting(ctx, t)
	if err != nil {
		return err
	}
	if facts.SettlementID != "" && t.Kind() == wager.KindWin {
		if err = accounting.SettleByID(ctx, facts.SettlementID); err != nil {
			return err
		}
		persisted, err := tx.Transactions().FindByID(ctx, t.ID())
		if err != nil {
			return err
		}
		*t = *persisted
		return nil
	}
	decision, err := wager.DecideAccounting(t, facts, u.clock.Now())
	if err != nil {
		return err
	}
	if decision.Failure != "" {
		return u.reject(ctx, tx, t, decision.Failure)
	}
	if decision.Wait {
		return u.waitReference(ctx, tx, t)
	}
	if decision.ReferenceID != "" {
		if err = t.ResolveReference(decision.ReferenceID); err != nil {
			return err
		}
	}
	if err = t.MarkProcessed(decision.Guarantee.Balance, u.clock.Now()); err != nil {
		return err
	}
	var entry wager.LedgerEntry
	if decision.GuaranteeDirection != "" {
		entry, err = wager.NewLedgerEntry(u.ids.NewID(), t.WalletID(), t.ID(), decision.GuaranteeDirection, t.Amount(), facts.Guarantee.Balance, u.clock.Now())
		if err != nil {
			return err
		}
	}
	if err = accounting.ApplyAccounting(ctx, t, facts, decision, u.clock.Now()); err != nil {
		return err
	}
	if decision.GuaranteeDirection != "" {
		if err = u.balanceEvent(ctx, tx, t, entry, decision.Guarantee.Version); err != nil {
			return err
		}
	}
	return u.processedEvent(ctx, tx, t)
}

internal/app/usecase/settlement.go:
package usecase

import (
	"context"
	"errors"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/settlement"
	"github.com/google/uuid"
	"strings"
)

type Settlements struct {
	uow   port.UnitOfWork
	clock port.Clock
	ids   port.IDGenerator
}

func NewSettlements(u port.UnitOfWork, c port.Clock, ids port.IDGenerator) *Settlements {
	return &Settlements{u, c, ids}
}
func (u *SubmitTransaction) Settlements() *Settlements { return NewSettlements(u.uow, u.clock, u.ids) }
func settlementStore(tx port.Tx) (port.SettlementStore, error) {
	s, ok := tx.(port.SettlementTransaction)
	if !ok {
		return nil, errors.New("settlement persistence is not configured")
	}
	return s.Settlements(), nil
}
func (u *Settlements) Create(ctx context.Context, b settlement.Bet) error {
	if _, err := uuid.Parse(b.ID); err != nil {
		return apperr.Invalid("invalid betId")
	}
	if strings.TrimSpace(b.ProviderID) == "" || strings.TrimSpace(b.RoundID) == "" || strings.TrimSpace(b.GameID) == "" {
		return apperr.Invalid("providerId, roundId and gameId required")
	}
	if _, err := money.Zero(b.Currency); err != nil {
		return apperr.Invalid("invalid currency")
	}
	b.ID = uuid.MustParse(b.ID).String()
	b.Status = "OPEN"
	b.CreatedAt = u.clock.Now()
	return u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		s, e := settlementStore(tx)
		if e != nil {
			return e
		}
		return s.CreateBet(ctx, b)
	})
}
func (u *Settlements) Confirm(ctx context.Context, betID string, d settlement.Distribution) (port.SettlementRecord, error) {
	id, err := uuid.Parse(betID)
	if err != nil {
		return port.SettlementRecord{}, apperr.Invalid("invalid betId")
	}
	if strings.TrimSpace(d.ResultID) == "" {
		return port.SettlementRecord{}, apperr.Invalid("resultId required")
	}
	for _, a := range d.Allocations {
		if !a.Money.IsPositive() {
			return port.SettlementRecord{}, apperr.Invalid("allocation must be positive")
		}
	}
	for _, r := range d.Returns {
		if !r.Money.IsPositive() {
			return port.SettlementRecord{}, apperr.Invalid("return must be positive")
		}
	}
	var out port.SettlementRecord
	err = u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		s, e := settlementStore(tx)
		if e != nil {
			return e
		}
		b, e := s.LockBet(ctx, id.String())
		if e != nil {
			return e
		}
		existing, e := s.FindSettlement(ctx, b.ID)
		if e == nil {
			if existing.ResultID != d.ResultID || existing.Hash != d.Hash() {
				return apperr.ErrIdempotencyConflict
			}
			out = existing
			return nil
		}
		if !errors.Is(e, apperr.ErrNotFound) {
			return e
		}
		cs, e := s.Commitments(ctx, b.ID)
		if e != nil {
			return e
		}
		if e = d.Validate(b, cs); e != nil {
			return e
		}
		out = port.SettlementRecord{ID: u.ids.NewID(), BetID: b.ID, ResultID: d.ResultID, Status: "CONFIRMED", Hash: d.Hash()}
		return s.SaveSettlement(ctx, out, b, d, cs, u.clock.Now())
	})
	if err != nil {
		return port.SettlementRecord{}, err
	}
	return out, nil
}

internal/app/usecase/settlement_audit.go:
package usecase

import (
	"context"
	"errors"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/settlement"
	"github.com/alexandre/wagering/internal/domain/wager"
	"github.com/google/uuid"
)

func auditStore(tx port.Tx) (port.SettlementAuditStore, error) {
	s, ok := tx.(port.SettlementAuditTransaction)
	if !ok {
		return nil, errors.New("settlement audit storage missing")
	}
	return s.SettlementAudit(), nil
}
func (u *Settlements) Get(ctx context.Context, id string) (port.SettlementAudit, error) {
	parsed, err := uuid.Parse(id)
	if err != nil {
		return port.SettlementAudit{}, apperr.Invalid("invalid settlementId")
	}
	var out port.SettlementAudit
	err = u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		r, err := auditStore(tx)
		if err != nil {
			return err
		}
		out, err = r.AuditSettlement(ctx, parsed.String())
		return err
	})
	if err != nil {
		return port.SettlementAudit{}, err
	}
	return out, nil
}

// Reverse compensates the complete settlement. Its ID is also the replay key:
// there can be only one full inverse of a settled result.
func (u *Settlements) Reverse(ctx context.Context, id string) (port.SettlementRecord, error) {
	parsed, err := uuid.Parse(id)
	if err != nil {
		return port.SettlementRecord{}, apperr.Invalid("invalid settlementId")
	}
	var out port.SettlementRecord
	err = u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		r, err := auditStore(tx)
		if err != nil {
			return err
		}
		record, facts, err := r.LockReversal(ctx, parsed.String())
		if err != nil {
			return err
		}
		if record.Status == "REVERSED" {
			out = record
			return nil
		}
		if err = settlement.ValidateReversal(facts, u.clock.Now()); err != nil {
			return err
		}
		for _, payment := range facts.Payments {
			// The settlement lock/status owns replay. A fresh opaque operation ID
			// avoids collisions with provider-supplied external transaction identities.
			reversalID := u.ids.NewID()
			external := "settlement-reversal:" + reversalID
			hash := wager.PayloadHash(wager.HashInput{ProviderID: payment.ProviderID, ExternalTransactionID: external, PlayerID: payment.PlayerID, WalletID: payment.WalletID, RoundID: payment.RoundID, GameID: payment.GameID, Kind: "ROLLBACK", Amount: payment.Amount.Amount(), Currency: payment.Amount.Currency(), ReferenceExternalTransactionID: payment.ExternalID})
			reversal, err := wager.NewExternal(wager.ExternalParams{ID: reversalID, ProviderID: payment.ProviderID, ExternalID: external, IdempotencyKey: external, PayloadHash: hash, WalletID: payment.WalletID, PlayerID: payment.PlayerID, RoundID: payment.RoundID, GameID: payment.GameID, Kind: wager.KindRollback, Amount: payment.Amount, ReferenceExternalID: payment.ExternalID, CorrelationID: record.ID}, u.clock.Now())
			if err != nil {
				return err
			}
			if err = reversal.ResolveReference(payment.ID); err != nil {
				return err
			}
			if err = tx.Transactions().Insert(ctx, reversal); err != nil {
				return err
			}
		}
		if err = r.ReverseSettlement(ctx, record.ID, u.clock.Now()); err != nil {
			return err
		}
		record.Status = "REVERSED"
		out = record
		return nil
	})
	if err != nil {
		return port.SettlementRecord{}, err
	}
	return out, nil
}

package usecase

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/google/uuid"
	"io"
	"time"
)

// ConsumeSettlementMessage is wired only to the private settlement queue.
// Wager ingress cannot select this handler by changing the envelope type.
type ConsumeSettlementMessage struct{ submit *SubmitTransaction }

func NewConsumeSettlementMessage(s *SubmitTransaction) *ConsumeSettlementMessage {
	return &ConsumeSettlementMessage{s}
}
func (u *ConsumeSettlementMessage) Handle(ctx context.Context, body []byte) error {
	var msg struct {
		MessageID  string    `json:"messageId"`
		Type       string    `json:"type"`
		OccurredAt time.Time `json:"occurredAt"`
		Data       struct {
			SettlementID string `json:"settlementId"`
		} `json:"data"`
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	if dec.Decode(&msg) != nil || dec.Decode(new(any)) != io.EOF || msg.MessageID == "" || msg.Type != "SettlementRequested" || msg.OccurredAt.IsZero() {
		return apperr.ErrInvalidMessage
	}
	id, err := uuid.Parse(msg.Data.SettlementID)
	if err != nil {
		return apperr.ErrInvalidMessage
	}
	sum := sha256.Sum256(body)
	return u.submit.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		executor, ok := tx.(port.SettlementDeliveryTransaction)
		if !ok {
			return apperr.Permanent(apperr.Invalid("settlement executor not configured"))
		}
		return executor.SettleDelivery(ctx, msg.MessageID, hex.EncodeToString(sum[:]), id.String(), u.submit.clock.Now())
	})
}

internal/app/usecase/transaction.go:
package usecase

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"github.com/google/uuid"
	"io"
	"log/slog"
	"time"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/wager"
)

type Source string

const (
	SourceHTTP Source = "HTTP"
	SourceSQS  Source = "SQS"
)

const InboxConsumerName = "wager-transactions"

// SubmitInput is shared by HTTP and SQS so both get the same idempotency/financial guarantees.
type SubmitInput struct {
	Source Source
	// AuthorizedProviderID comes from the token (HTTP). Empty for SQS (broker credentials/policies apply).
	AuthorizedProviderID string
	IdempotencyKey       string
	CorrelationID        string

	ProviderID, ExternalTransactionID, PlayerID, WalletID, RoundID, GameID string
	Kind, ReferenceExternalTransactionID                                   string
	BetID                                                                  string // Optional explicit membership for BET; never inferred from roundId.
	Amount, Currency                                                       string // raw strings, parsed in the use case

	// SQS only: inbox registration shares the domain transaction.
	InboxMessageID, InboxHash string
}

type SubmitResult struct {
	TransactionID    string
	Status           wager.Status
	Balance          *money.Money // observed at original processing time
	FailureCode      wager.FailureCode
	IdempotentReplay bool
}

type SubmitTransaction struct {
	uow     port.UnitOfWork
	clock   port.Clock
	ids     port.IDGenerator
	metrics port.Metrics
}

func NewSubmitTransaction(uow port.UnitOfWork, c port.Clock, ids port.IDGenerator, m port.Metrics) *SubmitTransaction {
	return &SubmitTransaction{uow, c, ids, m}
}

func (u *SubmitTransaction) Execute(ctx context.Context, in SubmitInput) (SubmitResult, error) {
	started := time.Now()
	defer func() { u.metrics.Latency("submit", time.Since(started)) }()
	if in.Source != SourceHTTP && in.Source != SourceSQS {
		return SubmitResult{}, apperr.Invalid("invalid source")
	}
	if in.Source == SourceHTTP && (in.AuthorizedProviderID == "" || in.AuthorizedProviderID != in.ProviderID) {
		return SubmitResult{}, apperr.ErrForbidden
	}
	if in.Source == SourceSQS && (in.InboxMessageID == "" || in.InboxHash == "") {
		return SubmitResult{}, apperr.Invalid("inbox identity required")
	}
	k, err := wager.ParseExternalKind(in.Kind)
	if err != nil {
		return SubmitResult{}, apperr.Invalid("%v", err)
	}
	m, err := money.Parse(in.Amount, in.Currency)
	if err != nil {
		return SubmitResult{}, apperr.Invalid("%v", err)
	}
	// UUID normalization avoids representation-dependent hashes and comparisons.
	player, err := uuid.Parse(in.PlayerID)
	if err != nil {
		return SubmitResult{}, apperr.Invalid("invalid playerId")
	}
	wid, err := uuid.Parse(in.WalletID)
	if err != nil {
		return SubmitResult{}, apperr.Invalid("invalid walletId")
	}
	in.PlayerID = player.String()
	in.WalletID = wid.String()
	if in.BetID != "" {
		bet, e := uuid.Parse(in.BetID)
		if e != nil || k != wager.KindBet {
			return SubmitResult{}, apperr.Invalid("betId requires BET and a valid UUID")
		}
		in.BetID = bet.String()
	}
	hash := wager.PayloadHash(wager.HashInput{BetID: in.BetID, ProviderID: in.ProviderID, ExternalTransactionID: in.ExternalTransactionID, PlayerID: in.PlayerID, WalletID: in.WalletID, RoundID: in.RoundID, GameID: in.GameID, Kind: in.Kind, ReferenceExternalTransactionID: in.ReferenceExternalTransactionID, Amount: m.Amount(), Currency: m.Currency()})
	t, err := wager.NewExternal(wager.ExternalParams{ID: u.ids.NewID(), ProviderID: in.ProviderID, ExternalID: in.ExternalTransactionID, IdempotencyKey: in.IdempotencyKey, PayloadHash: hash, WalletID: in.WalletID, PlayerID: in.PlayerID, RoundID: in.RoundID, GameID: in.GameID, Kind: k, Amount: m, ReferenceExternalID: in.ReferenceExternalTransactionID, CorrelationID: in.CorrelationID, CausationID: in.InboxMessageID}, u.clock.Now())
	if err != nil {
		return SubmitResult{}, apperr.Invalid("%v", err)
	}
	var result SubmitResult
	err = u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		if in.Source == SourceSQS {
			state, e := tx.Inbox().Begin(ctx, InboxConsumerName, in.InboxMessageID, in.InboxHash, u.clock.Now())
			if e != nil {
				return e
			}
			if state == port.InboxConflict {
				return apperr.ErrMessageConflict
			}
		}
		existing, e := tx.Transactions().FindByIdempotencyKey(ctx, in.ProviderID, in.IdempotencyKey)
		if e != nil && !errors.Is(e, apperr.ErrNotFound) {
			return e
		}
		if errors.Is(e, apperr.ErrNotFound) {
			// Missing wallets are invalid requests: no impossible FK/audit row is committed.
			if _, e = tx.Wallets().Get(ctx, in.WalletID); e != nil {
				return e
			}
			inserted, e := tx.Transactions().InsertPending(ctx, t)
			if e != nil {
				return e
			}
			if inserted {
				if in.BetID != "" {
					repo, err := settlementStore(tx)
					if err != nil {
						return err
					}
					bet, err := repo.LockBet(ctx, in.BetID)
					if err != nil {
						return err
					}
					if bet.ProviderID != in.ProviderID || bet.RoundID != in.RoundID || bet.Currency != in.Currency || bet.GameID != in.GameID {
						return apperr.Invalid("BET context differs from explicit bet")
					}
					if err = repo.BindBet(ctx, t.ID(), bet.ID); err != nil {
						return err
					}
				}
				if e = u.process(ctx, tx, t); e != nil {
					return e
				}
				existing = t
			} else {
				existing, e = tx.Transactions().FindByIdempotencyKey(ctx, in.ProviderID, in.IdempotencyKey)
				if errors.Is(e, apperr.ErrNotFound) {
					return apperr.ErrIdempotencyConflict
				}
				if e != nil {
					return e
				}
				result.IdempotentReplay = true
			}
		} else {
			result.IdempotentReplay = true
		}
		s := existing.Snapshot()
		if s.PayloadHash != hash || s.IdempotencyKey != in.IdempotencyKey {
			return apperr.ErrIdempotencyConflict
		}
		result.TransactionID = s.ID
		result.Status = s.Status
		result.Balance = s.BalanceAfter
		result.FailureCode = s.FailureCode
		if in.Source == SourceSQS {
			if binder, ok := tx.Inbox().(interface {
				BindTransaction(context.Context, string, string, string) error
			}); ok {
				if err := binder.BindTransaction(ctx, InboxConsumerName, in.InboxMessageID, s.ID); err != nil {
					return err
				}
			}
			return tx.Inbox().Complete(ctx, InboxConsumerName, in.InboxMessageID, u.clock.Now())
		}
		return nil
	})
	if err == nil {
		u.metrics.TxResult(in.Kind, string(result.Status))
		if result.IdempotentReplay {
			u.metrics.Duplicate(string(in.Source))
		}
		slog.InfoContext(ctx, "transaction handled", "correlationId", in.CorrelationID, "messageId", in.InboxMessageID, "transactionId", result.TransactionID, "walletId", in.WalletID, "providerId", in.ProviderID, "status", result.Status)
	}
	if err != nil {
		slog.WarnContext(ctx, "transaction handling failed", "correlationId", in.CorrelationID, "messageId", in.InboxMessageID, "transactionId", t.ID(), "walletId", in.WalletID, "providerId", in.ProviderID, "transient", apperr.IsTransient(err))
	}
	if apperr.IsTransient(err) {
		u.metrics.Retry("submit")
	}
	if errors.Is(err, apperr.ErrConcurrentModification) {
		u.metrics.ConcurrencyConflict()
	}
	return result, err
}

// ---- GetTransaction -------------------------------------------------------

// Scope restricts reads: providers only see their own transactions (inclusive replays).
type Scope struct {
	ProviderID string
	Internal   bool
}

type TransactionView struct {
	ID, ProviderID, ExternalTransactionID, WalletID string
	Kind                                            wager.Kind
	Status                                          wager.Status
	Amount                                          money.Money
	Balance                                         *money.Money
	FailureCode                                     wager.FailureCode
	NextAttemptAt                                   *time.Time
}

type GetTransaction struct{ uow port.UnitOfWork }

func NewGetTransaction(uow port.UnitOfWork) *GetTransaction { return &GetTransaction{uow} }

func (u *GetTransaction) ByID(ctx context.Context, id string, s Scope) (TransactionView, error) {
	var out TransactionView
	err := u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		t, e := tx.Transactions().FindByID(ctx, id)
		if e != nil {
			return e
		}
		v := t.Snapshot()
		if !s.Internal && (s.ProviderID == "" || v.ProviderID != s.ProviderID) {
			return apperr.ErrNotFound
		}
		out = transactionView(t)
		return nil
	})
	return out, err
}

func (u *GetTransaction) ByExternalID(ctx context.Context, providerID, externalID string, s Scope) (TransactionView, error) {
	if !s.Internal && (s.ProviderID == "" || providerID != s.ProviderID) {
		return TransactionView{}, apperr.ErrNotFound
	}
	var out TransactionView
	err := u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		t, e := tx.Transactions().FindByExternalID(ctx, providerID, externalID)
		if e != nil {
			return e
		}
		out = transactionView(t)
		return nil
	})
	return out, err
}

// ---- ConsumeWagerMessage (SQS entrypoint) ---------------------------------

// WagerTransactionRequested mirrors the SQS message contract (see docs/CONTRACTS.md).
type WagerTransactionRequested struct {
	MessageID  string    `json:"messageId"`
	Type       string    `json:"type"`
	OccurredAt time.Time `json:"occurredAt"`
	Data       struct {
		ProviderID                     string `json:"providerId"`
		ExternalTransactionID          string `json:"externalTransactionId"`
		IdempotencyKey                 string `json:"idempotencyKey"`
		PlayerID                       string `json:"playerId"`
		WalletID                       string `json:"walletId"`
		RoundID                        string `json:"roundId"`
		GameID                         string `json:"gameId"`
		Kind                           string `json:"kind"`
		BetID                          string `json:"betId,omitempty"`
		ReferenceExternalTransactionID string `json:"referenceExternalTransactionId,omitempty"`
		Money                          struct {
			Amount   string `json:"amount"`
			Currency string `json:"currency"`
		} `json:"money"`
	} `json:"data"`
}

type ConsumeWagerMessage struct{ submit *SubmitTransaction }

func NewConsumeWagerMessage(s *SubmitTransaction) *ConsumeWagerMessage {
	return &ConsumeWagerMessage{s}
}

// Handle parses the envelope and delegates to SubmitTransaction (same use case as HTTP).
// Invalid messages return apperr.ErrInvalidMessage (permanent → DLQ).
func (u *ConsumeWagerMessage) Handle(ctx context.Context, body []byte) error {
	var m WagerTransactionRequested
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	dec.UseNumber()
	if err := dec.Decode(&m); err != nil {
		return fmt.Errorf("%w: %v", apperr.ErrInvalidMessage, err)
	}
	if dec.Decode(new(any)) != io.EOF {
		return apperr.ErrInvalidMessage
	}
	if m.OccurredAt.IsZero() {
		return apperr.ErrInvalidMessage
	}
	if m.MessageID == "" || m.Type != "WagerTransactionRequested" || m.Data.IdempotencyKey == "" {
		return fmt.Errorf("%w: missing messageId/type/idempotencyKey", apperr.ErrInvalidMessage)
	}
	sum := sha256.Sum256(body)
	_, err := u.submit.Execute(ctx, SubmitInput{
		Source:         SourceSQS,
		IdempotencyKey: m.Data.IdempotencyKey,
		CorrelationID:  m.MessageID,
		BetID:          m.Data.BetID,
		ProviderID:     m.Data.ProviderID, ExternalTransactionID: m.Data.ExternalTransactionID,
		PlayerID: m.Data.PlayerID, WalletID: m.Data.WalletID, RoundID: m.Data.RoundID, GameID: m.Data.GameID,
		Kind: m.Data.Kind, ReferenceExternalTransactionID: m.Data.ReferenceExternalTransactionID,
		Amount: m.Data.Money.Amount, Currency: m.Data.Money.Currency,
		InboxMessageID: m.MessageID, InboxHash: hex.EncodeToString(sum[:]),
	})
	return err
}

func transactionView(t *wager.Transaction) TransactionView {
	s := t.Snapshot()
	return TransactionView{s.ID, s.ProviderID, s.ExternalID, s.WalletID, s.Kind, s.Status, s.Amount, s.BalanceAfter, s.FailureCode, s.NextAttemptAt}
}

