package usecase

import (
	"context"
	"github.com/alexandre/wagering/internal/domain/wager"
	"github.com/alexandre/wagering/internal/domain/wallet"
	"github.com/google/uuid"
	"log/slog"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
)

type WalletView struct {
	ID, PlayerID string
	Balance      money.Money
	Version      int64
}

// ---- OpenWallet -----------------------------------------------------------

type OpenWalletInput struct {
	PlayerID       string
	InitialBalance money.Money
}

type OpenWallet struct {
	uow   port.UnitOfWork
	clock port.Clock
	ids   port.IDGenerator
}

func NewOpenWallet(uow port.UnitOfWork, clock port.Clock, ids port.IDGenerator) *OpenWallet {
	return &OpenWallet{uow, clock, ids}
}

func (u *OpenWallet) Execute(ctx context.Context, in OpenWalletInput) (WalletView, error) {
	player, err := uuid.Parse(in.PlayerID)
	if err != nil {
		return WalletView{}, apperr.Invalid("invalid playerId")
	}
	w, err := wallet.New(u.ids.NewID(), player.String(), in.InitialBalance, u.clock.Now())
	if err != nil {
		return WalletView{}, apperr.Invalid("%v", err)
	}
	err = u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		if err := tx.Wallets().Create(ctx, w); err != nil {
			return err
		}
		if !in.InitialBalance.IsPositive() {
			return nil
		}
		t, err := wager.NewOpening(u.ids.NewID(), w.ID(), w.PlayerID(), in.InitialBalance, u.clock.Now())
		if err != nil {
			return err
		}
		if err = tx.Transactions().Insert(ctx, t); err != nil {
			return err
		}
		// wallet.New has already validated the currency.
		zero, _ := money.Zero(w.Currency())
		entry, err := wager.NewLedgerEntry(u.ids.NewID(), w.ID(), t.ID(), wager.Credit, in.InitialBalance, zero, u.clock.Now())
		if err != nil {
			return err
		}
		if err = tx.Ledger().Append(ctx, entry); err != nil {
			return err
		}
		helper := SubmitTransaction{clock: u.clock, ids: u.ids}
		if err = helper.processedEvent(ctx, tx, t); err != nil {
			return err
		}
		return helper.balanceEvent(ctx, tx, t, entry, 1)
	})
	return WalletView{w.ID(), w.PlayerID(), w.Balance(), w.Version()}, err
}

// ---- GetWallet ------------------------------------------------------------

type GetWallet struct{ uow port.UnitOfWork }

func NewGetWallet(uow port.UnitOfWork) *GetWallet { return &GetWallet{uow} }

func (u *GetWallet) Execute(ctx context.Context, walletID string) (WalletView, error) {
	var v WalletView
	err := u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		w, e := tx.Wallets().Get(ctx, walletID)
		if e != nil {
			return e
		}
		v = WalletView{w.ID(), w.PlayerID(), w.Balance(), w.Version()}
		return nil
	})
	return v, err
}

// ---- ListLedger -----------------------------------------------------------

type ListLedger struct{ uow port.UnitOfWork }

func NewListLedger(uow port.UnitOfWork) *ListLedger { return &ListLedger{uow} }

func (u *ListLedger) Execute(ctx context.Context, walletID, cursor string, limit int) (port.LedgerPage, error) {
	var page port.LedgerPage
	err := u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		if _, e := tx.Wallets().Get(ctx, walletID); e != nil {
			return e
		}
		var e error
		page, e = tx.Ledger().List(ctx, walletID, cursor, limit)
		return e
	})
	return page, err
}

// ---- ReconcileWallet ------------------------------------------------------

type ReconciliationResult struct {
	WalletID                       string
	Stored, Calculated, Difference money.Money
	Consistent                     bool
	CheckedEntries                 int64
}

type ReconcileWallet struct {
	uow     port.UnitOfWork
	metrics port.Metrics
}

func NewReconcileWallet(uow port.UnitOfWork, m port.Metrics) *ReconcileWallet {
	return &ReconcileWallet{uow, m}
}

func (u *ReconcileWallet) Execute(ctx context.Context, walletID string) (ReconciliationResult, error) {
	var out ReconciliationResult
	err := u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		w, e := tx.Wallets().Get(ctx, walletID)
		if e != nil {
			return e
		}
		totals, e := tx.Ledger().Totals(ctx, walletID)
		if e != nil {
			return e
		}
		diff, e := w.Balance().Sub(totals.Calculated)
		if e != nil {
			return e
		}
		out = ReconciliationResult{walletID, w.Balance(), totals.Calculated, diff, diff.IsZero(), totals.Entries}
		return nil
	})
	if err == nil && !out.Consistent {
		u.metrics.ReconciliationDivergence()
		slog.ErrorContext(ctx, "reconciliation divergence", "walletId", walletID)
	}
	return out, err
}

internal/app/usecase/workers.go:
package usecase

import (
	"context"
	"encoding/json"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/event"
	"github.com/alexandre/wagering/internal/domain/wager"
	"github.com/alexandre/wagering/internal/platform/failpoint"
	"log/slog"
	"time"
)

const (
	MaxReferenceAttempts = 8
	BatchSize            = 20
)

func Backoff(attempt int) time.Duration { return time.Second << min(max(attempt, 0), 6) }

type ProcessPendingReferences struct {
	uow     port.UnitOfWork
	clock   port.Clock
	metrics port.Metrics
	submit  *SubmitTransaction
}

func NewProcessPendingReferences(u port.UnitOfWork, c port.Clock, m port.Metrics, s *SubmitTransaction) *ProcessPendingReferences {
	return &ProcessPendingReferences{u, c, m, s}
}
func (u *ProcessPendingReferences) RunOnce(ctx context.Context) (int, error) {
	n := 0
	// One wallet/transaction per SQL transaction avoids cross-wallet lock cycles.
	for n < BatchSize && ctx.Err() == nil {
		found := false
		var acceptedID string
		var outcome *wager.Transaction
		err := u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
			rows, e := tx.Transactions().ClaimDue(ctx, u.clock.Now(), 1)
			if e != nil {
				return e
			}
			if len(rows) == 0 {
				return nil
			}
			found = true
			acceptedID = rows[0].ID()
			outcome = rows[0]
			return u.submit.process(ctx, tx, rows[0])
		})
		if err != nil {
			if outcome != nil {
				s := outcome.Snapshot()
				slog.ErrorContext(ctx, "reference processing failed", "transactionId", s.ID, "walletId", s.WalletID, "providerId", s.ProviderID, "correlationId", s.CorrelationID, "messageId", s.CausationID, "err", err)
			}
			if apperr.IsTransient(err) {
				u.metrics.Retry("reference-infrastructure")
			}
			if acceptedID != "" && apperr.IsPermanent(err) {
				recordedFailure := false
				failureErr := u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
					t, e := tx.Transactions().FindByID(ctx, acceptedID)
					if e != nil {
						return e
					}
					if t.Status().IsTerminal() {
						return nil
					}
					if e = t.Fail(wager.FailInternalPermanent, u.clock.Now()); e != nil {
						return e
					}
					if e = tx.Transactions().Update(ctx, t); e != nil {
						return e
					}
					recordedFailure = true
					return nil
				})
				if failureErr != nil {
					return n, failureErr
				}
				if recordedFailure {
					slog.ErrorContext(ctx, "accepted operation failed permanently", "transactionId", acceptedID)
					u.metrics.TxResult(string(outcome.Kind()), "FAILED")
				}
				n++
				continue
			}
			return n, err
		}
		if !found {
			break
		}
		n++
		u.metrics.TxResult(string(outcome.Kind()), string(outcome.Status()))
		u.metrics.Retry("reference")
	}
	return n, ctx.Err()
}

type PublishOutbox struct {
	uow     port.UnitOfWork
	pub     port.EventPublisher
	clock   port.Clock
	metrics port.Metrics
}

func NewPublishOutbox(u port.UnitOfWork, p port.EventPublisher, c port.Clock, m port.Metrics) *PublishOutbox {
	return &PublishOutbox{u, p, c, m}
}
func (u *PublishOutbox) RunOnce(ctx context.Context) (int, error) {
	const outboxLease = 30 * time.Second
	var events []event.Outgoing
	err := u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
		var e error
		events, e = tx.Outbox().ClaimBatch(ctx, u.clock.Now(), 1, outboxLease)
		return e
	})
	if err != nil {
		return 0, err
	}
	for _, ev := range events {
		var ids struct {
			CorrelationID string `json:"correlationId"`
			CausationID   string `json:"causationId"`
			Data          struct {
				TransactionID string `json:"transactionId"`
				ProviderID    string `json:"providerId"`
			} `json:"data"`
		}
		_ = json.Unmarshal(ev.Payload(), &ids)
		log := slog.Default().With("eventId", ev.EventID(), "walletId", ev.AggregateID(), "transactionId", ids.Data.TransactionID, "providerId", ids.Data.ProviderID, "correlationId", ids.CorrelationID, "messageId", ids.CausationID, "attempt", ev.Attempts())
		sendCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		sendErr := u.pub.Publish(sendCtx, ev)
		if failpoint.Enabled && sendErr == nil {
			failpoint.Hit("after_publish_before_mark")
		}
		cancel()
		if sendErr != nil {
			log.Warn("event publication failed", "err", sendErr)
		}
		err = u.uow.Do(ctx, func(ctx context.Context, tx port.Tx) error {
			if sendErr != nil {
				u.metrics.Retry("outbox")
				return tx.Outbox().Reschedule(ctx, ev.EventID(), ev.Attempts(), u.clock.Now().Add(Backoff(ev.Attempts())))
			}
			return tx.Outbox().MarkPublished(ctx, ev.EventID(), ev.Attempts(), u.clock.Now())
		})
		if err != nil {
			log.Error("event publication confirmation failed", "err", err)
			return 0, err
		}
		if sendErr == nil {
			log.Info("event published")
		}
	}
	// Include delayed/leased work, and clear the gauge when the backlog is empty.
	err = u.uow.DoSnapshot(ctx, func(ctx context.Context, tx port.Tx) error {
		oldest, e := tx.Outbox().OldestPending(ctx)
		if e != nil {
			return e
		}
		lag := time.Duration(0)
		if oldest != nil {
			lag = max(time.Duration(0), u.clock.Now().Sub(*oldest))
		}
		u.metrics.OutboxLag(lag)
		return nil
	})
	return len(events), err
}

internal/domain/event/event.go:
// Package event defines the integration event envelope, typed payloads and constructors.
// Type and version are fixed by the constructors.
package event

import (
	"encoding/json"
	"time"

	"github.com/alexandre/wagering/internal/domain/money"
)

const (
	TypeSettlementRequested              = "SettlementRequested"
	TypeWagerTransactionProcessed        = "WagerTransactionProcessed"
	TypeWagerTransactionRejected         = "WagerTransactionRejected"
	TypeWalletBalanceChanged             = "WalletBalanceChanged"
	TypeWagerTransactionPendingReference = "WagerTransactionPendingReference"
)

type Envelope[T any] struct {
	EventID       string    `json:"eventId"`
	EventType     string    `json:"eventType"`
	AggregateID   string    `json:"aggregateId"`
	CorrelationID string    `json:"correlationId"`
	CausationID   string    `json:"causationId,omitempty"`
	OccurredAt    time.Time `json:"occurredAt"`
	Version       int       `json:"version"`
	Data          T         `json:"data"`
}

type MoneyDTO struct {
	Amount   string `json:"amount"`
	Currency string `json:"currency"`
}

func ToMoneyDTO(m money.Money) MoneyDTO { return MoneyDTO{m.Amount(), m.Currency()} }

// Meta is what the application layer supplies; the constructors add type/version.
type Meta struct {
	EventID, AggregateID, CorrelationID, CausationID string
	OccurredAt                                       time.Time
}

// Outgoing is the immutable outbox snapshot of an event (payload = serialized envelope).
type Outgoing struct {
	eventID, aggregateID, typ, payload string
	version, attempts                  int
	occurredAt                         time.Time
}

func (e Outgoing) EventID() string       { return e.eventID }
func (e Outgoing) AggregateID() string   { return e.aggregateID }
func (e Outgoing) Type() string          { return e.typ }
func (e Outgoing) Version() int          { return e.version }
func (e Outgoing) Attempts() int         { return e.attempts }
func (e Outgoing) OccurredAt() time.Time { return e.occurredAt }
func (e Outgoing) Payload() []byte       { return []byte(e.payload) }

func newEnvelope[T any](m Meta, typ string, data T) Envelope[T] {
	return Envelope[T]{m.EventID, typ, m.AggregateID, m.CorrelationID, m.CausationID, m.OccurredAt.UTC(), 1, data}
}

func (e Envelope[T]) ToOutgoing() (Outgoing, error) {
	if err := validate(e.EventID, e.AggregateID, e.CorrelationID, e.EventType, e.Version, e.OccurredAt, e.Data); err != nil {
		return Outgoing{}, err
	}
	b, err := json.Marshal(e)
	if err != nil {
		return Outgoing{}, err
	}
	return Outgoing{eventID: e.EventID, aggregateID: e.AggregateID, typ: e.EventType, version: e.Version, occurredAt: e.OccurredAt.UTC(), payload: string(b)}, nil
}

// ---- Payloads -------------------------------------------------------------

type ProcessedData struct {
	TransactionID         string   `json:"transactionId"`
	Kind                  string   `json:"kind"`
	WalletID              string   `json:"walletId"`
	PlayerID              string   `json:"playerId"`
	ProviderID            string   `json:"providerId,omitempty"`
	ExternalTransactionID string   `json:"externalTransactionId,omitempty"`
	RoundID               string   `json:"roundId,omitempty"`
	Money                 MoneyDTO `json:"money"`
}

type RejectedData struct {
	TransactionID         string `json:"transactionId"`
	Kind                  string `json:"kind"`
	WalletID              string `json:"walletId"`
	ProviderID            string `json:"providerId"`
	ExternalTransactionID string `json:"externalTransactionId"`
	FailureCode           string `json:"failureCode"`
}

type BalanceChangedData struct {
	WalletID      string   `json:"walletId"`
	TransactionID string   `json:"transactionId"`
	Direction     string   `json:"direction"`
	Money         MoneyDTO `json:"money"`
	BalanceBefore MoneyDTO `json:"balanceBefore"`
	BalanceAfter  MoneyDTO `json:"balanceAfter"`
	WalletVersion int64    `json:"walletVersion"`
}

type PendingReferenceData struct {
	TransactionID                  string    `json:"transactionId"`
	ProviderID                     string    `json:"providerId"`
	ExternalTransactionID          string    `json:"externalTransactionId"`
	ReferenceExternalTransactionID string    `json:"referenceExternalTransactionId"`
	NextAttemptAt                  time.Time `json:"nextAttemptAt"`
	ExpiresAt                      time.Time `json:"expiresAt"`
}

// ---- Constructors ---------------------------------------------------------

func NewProcessed(m Meta, d ProcessedData) Envelope[ProcessedData] {
	return newEnvelope(m, TypeWagerTransactionProcessed, d)
}
func NewRejected(m Meta, d RejectedData) Envelope[RejectedData] {
	return newEnvelope(m, TypeWagerTransactionRejected, d)
}
func NewBalanceChanged(m Meta, d BalanceChangedData) Envelope[BalanceChangedData] {
	return newEnvelope(m, TypeWalletBalanceChanged, d)
}
func NewPendingReference(m Meta, d PendingReferenceData) Envelope[PendingReferenceData] {
	return newEnvelope(m, TypeWagerTransactionPendingReference, d)
}

// SettlementRequestedData identifies a sealed plan; no money is recomputed by
// consumers from a message payload.
type SettlementRequestedData struct {
	SettlementID string `json:"settlementId"`
}

func NewSettlementRequested(m Meta, d SettlementRequestedData) Envelope[SettlementRequestedData] {
	return newEnvelope(m, TypeSettlementRequested, d)
}

internal/domain/event/validation.go:
package event

import (
	"encoding/json"
	"errors"
	"fmt"
	"github.com/alexandre/wagering/internal/domain/money"
	"time"
)

var ErrInvalidEvent = errors.New("invalid integration event")

func invalidEvent(reason string) error { return fmt.Errorf("%w: %s", ErrInvalidEvent, reason) }
func exactMoney(d MoneyDTO) (money.Money, error) {
	m, err := money.Parse(d.Amount, d.Currency)
	if err != nil || m.Amount() != d.Amount || m.IsNegative() {
		return money.Money{}, invalidEvent("noncanonical money")
	}
	return m, nil
}
func externalKind(k string) bool {
	return k == "BET" || k == "WIN" || k == "LOSS" || k == "REFUND" || k == "ROLLBACK"
}
func validate(id, aggregate, correlation, typ string, version int, occurred time.Time, data any) error {
	if id == "" || aggregate == "" || correlation == "" || version != 1 || occurred.IsZero() {
		return invalidEvent("envelope metadata")
	}
	switch d := data.(type) {
	case SettlementRequestedData:
		if typ != TypeSettlementRequested || d.SettlementID == "" {
			return invalidEvent("settlement identity")
		}
	case ProcessedData:
		if typ != TypeWagerTransactionProcessed || d.TransactionID == "" || d.WalletID != aggregate || d.PlayerID == "" {
			return invalidEvent("processed identity")
		}
		m, err := exactMoney(d.Money)
		if err != nil {
			return err
		}
		if d.Kind == "OPENING" {
			if d.ProviderID != "" || d.ExternalTransactionID != "" || d.RoundID != "" || !m.IsPositive() {
				return invalidEvent("opening metadata")
			}
		} else if !externalKind(d.Kind) || d.ProviderID == "" || d.ExternalTransactionID == "" || d.RoundID == "" || (d.Kind == "LOSS" && m.Minor() != 0) || (d.Kind != "LOSS" && !m.IsPositive()) {
			return invalidEvent("external processed fact")
		}
	case RejectedData:
		if typ != TypeWagerTransactionRejected || d.TransactionID == "" || d.WalletID != aggregate || !externalKind(d.Kind) || d.ProviderID == "" || d.ExternalTransactionID == "" || d.FailureCode == "" {
			return invalidEvent("rejected fact")
		}
	case BalanceChangedData:
		if typ != TypeWalletBalanceChanged || d.TransactionID == "" || d.WalletID != aggregate || d.WalletVersion < 1 {
			return invalidEvent("balance identity")
		}
		m, err := exactMoney(d.Money)
		if err != nil || !m.IsPositive() {
			return invalidEvent("movement amount")
		}
		before, err := exactMoney(d.BalanceBefore)
		if err != nil {
			return err
		}
		after, err := exactMoney(d.BalanceAfter)
		if err != nil {
			return err
		}
		var expected money.Money
		switch d.Direction {
		case "CREDIT":
			expected, err = before.Add(m)
		case "DEBIT":
			expected, err = before.Sub(m)
		default:
			return invalidEvent("direction")
		}
		if err != nil || expected.Currency() != after.Currency() || expected.Minor() != after.Minor() {
			return invalidEvent("balance equation")
		}
	case PendingReferenceData:
		if typ != TypeWagerTransactionPendingReference || d.TransactionID == "" || d.ProviderID == "" || d.ExternalTransactionID == "" || d.ReferenceExternalTransactionID == "" || !d.NextAttemptAt.After(occurred) || !d.ExpiresAt.After(occurred) {
			return invalidEvent("pending reference fact")
		}
	default:
		return invalidEvent("unknown payload type")
	}
	return nil
}

// RehydrateOutgoing validates the stored snapshot without creating a new fact.
// PostgreSQL timestamps have microsecond precision; the JSON keeps the original instant.
func RehydrateOutgoing(id, aggregate, typ string, payload []byte, occurred time.Time, attempts int) (Outgoing, error) {
	var e Envelope[json.RawMessage]
	if err := json.Unmarshal(payload, &e); err != nil {
		return Outgoing{}, invalidEvent("stored JSON")
	}
	if attempts < 0 || id != e.EventID || aggregate != e.AggregateID || typ != e.EventType || !occurred.Truncate(time.Microsecond).Equal(e.OccurredAt.Truncate(time.Microsecond)) {
		return Outgoing{}, invalidEvent("stored metadata mismatch")
	}
	var data any
	switch typ {
	case TypeSettlementRequested:
		data = &SettlementRequestedData{}
	case TypeWagerTransactionProcessed:
		data = &ProcessedData{}
	case TypeWagerTransactionRejected:
		data = &RejectedData{}
	case TypeWalletBalanceChanged:
		data = &BalanceChangedData{}
	case TypeWagerTransactionPendingReference:
		data = &PendingReferenceData{}
	default:
		return Outgoing{}, invalidEvent("stored type")
	}
	if err := json.Unmarshal(e.Data, data); err != nil {
		return Outgoing{}, invalidEvent("stored payload")
	}
	switch d := data.(type) {
	case *SettlementRequestedData:
		data = *d
	case *ProcessedData:
		data = *d
	case *RejectedData:
		data = *d
	case *BalanceChangedData:
		data = *d
	case *PendingReferenceData:
		data = *d
	}
	if err := validate(e.EventID, e.AggregateID, e.CorrelationID, e.EventType, e.Version, e.OccurredAt, data); err != nil {
		return Outgoing{}, err
	}
	return Outgoing{eventID: id, aggregateID: aggregate, typ: typ, payload: string(payload), version: e.Version, attempts: attempts, occurredAt: e.OccurredAt.UTC()}, nil
}

