// Package settlement validates declared outcomes without I/O or balance mutation.
package settlement

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"math/big"
	"strings"
	"time"

	"github.com/alexandre/wagering/internal/domain/money"
)

var ErrDistribution = errors.New("invalid settlement distribution")

type Bet struct {
	ID, ProviderID, RoundID, GameID, Currency, Status string
	CreatedAt                                         time.Time
}
type Commitment struct {
	ID, TransactionID, ExternalID, WalletID, PlayerID, GameID string
	Remaining                                                 money.Money
}
type Transfer struct {
	From  string      `json:"fromExternalTransactionId"`
	To    string      `json:"toExternalTransactionId"`
	Money money.Money `json:"money"`
}
type Return struct {
	ExternalID string      `json:"externalTransactionId"`
	Money      money.Money `json:"money"`
}
type Distribution struct {
	ResultID    string     `json:"resultId"`
	Allocations []Transfer `json:"allocations"`
	Returns     []Return   `json:"returns"`
}

func (d Distribution) Hash() string {
	b, _ := json.Marshal(d)
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

// Validate compares each declared result with the complete locked set of stakes.
// It never chooses winners or distributes a remainder/rounding difference.
func (d Distribution) Validate(b Bet, commitments []Commitment) error {
	fail := func(reason string) error { return fmt.Errorf("%w: %s", ErrDistribution, reason) }
	if b.Status != "OPEN" || len(commitments) == 0 || strings.TrimSpace(d.ResultID) == "" || len(d.Returns) == 0 {
		return fail("open nonempty bet and result required")
	}
	balances := map[string]*big.Int{}
	accounts := map[string]string{}
	for _, c := range commitments {
		if c.Remaining.Currency() != b.Currency || c.Remaining.Minor() < 0 || balances[c.ExternalID] != nil {
			return fail("invalid commitment")
		}
		balances[c.ExternalID] = big.NewInt(c.Remaining.Minor())
		accounts[c.ExternalID] = c.WalletID
	}
	payments := map[string]bool{}
	for _, r := range d.Returns {
		if balances[r.ExternalID] == nil || payments[r.ExternalID] || !r.Money.IsPositive() || r.Money.Currency() != b.Currency {
			return fail("invalid return")
		}
		payments[r.ExternalID] = true
	}
	for _, a := range d.Allocations {
		from, to := balances[a.From], balances[a.To]
		if from == nil || to == nil || a.From == a.To || accounts[a.From] == accounts[a.To] || !payments[a.To] || !a.Money.IsPositive() || a.Money.Currency() != b.Currency {
			return fail("invalid allocation")
		}
		amount := big.NewInt(a.Money.Minor())
		if from.Cmp(amount) < 0 {
			return fail("allocation exceeds eligible stake")
		}
		from.Sub(from, amount)
		to.Add(to, amount)
	}
	for _, r := range d.Returns {
		balances[r.ExternalID].Sub(balances[r.ExternalID], big.NewInt(r.Money.Minor()))
	}
	for _, n := range balances {
		if n.Sign() != 0 {
			return fail("distribution does not conserve each commitment")
		}
	}
	return nil
}

internal/domain/settlement/reversal.go:
package settlement

import (
	"errors"
	"fmt"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/wager"
	"github.com/alexandre/wagering/internal/domain/wallet"
	"time"
)

var ErrReversalState = errors.New("settlement is not processed")

// ReversalJournal is an original journal in descending posting order.
type ReversalJournal struct {
	DebitAccountID, CreditAccountID string
	Amount                          money.Money
}
type ReversalFacts struct {
	Status   string
	Payments []wager.Snapshot
	Journals []ReversalJournal
	Accounts map[string]wallet.Snapshot
}

// ValidateReversal simulates the exact inverse in memory, including intermediate
// balances and overflow. It never edits the original journals or chooses a subset.
func ValidateReversal(f ReversalFacts, now time.Time) error {
	if f.Status != "PROCESSED" {
		return ErrReversalState
	}
	if len(f.Payments) == 0 || len(f.Journals) == 0 {
		return fmt.Errorf("%w: missing accounting history", ErrReversalState)
	}
	for _, p := range f.Payments {
		if p.Kind != wager.KindWin || p.Status != wager.StatusProcessed {
			return fmt.Errorf("%w: payment is not a processed WIN", ErrReversalState)
		}
	}
	accounts := map[string]*wallet.Wallet{}
	for id, s := range f.Accounts {
		w, err := wallet.Rehydrate(s)
		if err != nil {
			return err
		}
		accounts[id] = w
	}
	for _, j := range f.Journals {
		debit, credit := accounts[j.CreditAccountID], accounts[j.DebitAccountID]
		if debit == nil || credit == nil || debit == credit {
			return fmt.Errorf("%w: missing counterparty", ErrReversalState)
		}
		if _, _, err := debit.Debit(j.Amount, now); err != nil {
			if errors.Is(err, wallet.ErrInsufficientFunds) {
				return wager.ErrReversalInsufficient
			}
			return err
		}
		if _, _, err := credit.Credit(j.Amount, now); err != nil {
			if errors.Is(err, money.ErrOverflow) {
				return &wager.DomainError{Code: "BALANCE_OVERFLOW", Msg: "settlement reversal overflows counterparty"}
			}
			return err
		}
	}
	return nil
}

internal/domain/wager/accounting.go:
package wager

import (
	"errors"
	"time"

	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/wallet"
)

// AccountingFacts is a locked persistence snapshot, not a command. A wallet
// exposes its guarantee balance; its operational account holds committed stakes.
type AccountingFacts struct {
	Guarantee, Operational                                wallet.Snapshot
	Reference                                             *Snapshot
	ReferenceCandidates                                   int
	BetID, BetStatus, SettlementID, ReferenceSettlementID string
	CommitmentID                                          string
	Remaining                                             int64
	AlreadyReversed                                       bool
	OriginalJournalID                                     string
	Restores                                              []CommitmentRestore
}

type CommitmentRestore struct {
	EffectID, CommitmentID string
	Amount                 int64
}

// AccountingDecision contains only a domain decision. Storage adapters must not
// reinterpret the operation or choose a different debit/credit counterparty.
type AccountingDecision struct {
	Failure                FailureCode
	Wait                   bool
	ReferenceID            string
	Guarantee, Operational wallet.Snapshot
	GuaranteeDirection     Direction
	NewCommitment          bool
	ConsumeCommitmentID    string
	ReverseJournalID       string
	Restores               []CommitmentRestore
}

func DecideAccounting(t *Transaction, f AccountingFacts, now time.Time) (AccountingDecision, error) {
	d := AccountingDecision{Guarantee: f.Guarantee, Operational: f.Operational}
	reject := func(code FailureCode) (AccountingDecision, error) { d.Failure = code; return d, nil }
	if err := t.ensureOpen(); err != nil {
		return d, err
	}
	if f.Guarantee.ID == "" || f.Operational.ID == "" || f.Guarantee.ID == f.Operational.ID || f.Guarantee.PlayerID != f.Operational.PlayerID || f.Guarantee.Balance.Currency() != f.Operational.Balance.Currency() {
		return d, wallet.ErrInvalidWallet
	}
	s := t.Snapshot()
	if t.ReferenceExpired(now) {
		return reject(FailReferenceNotFound)
	}
	if f.Guarantee.PlayerID != s.PlayerID {
		return reject(FailReferenceMismatch)
	}
	if f.Guarantee.Balance.Currency() != s.Amount.Currency() {
		return reject(FailCurrencyMismatch)
	}
	r := f.Reference
	if s.ReferenceExternalID != "" && r == nil {
		d.Wait = true
		return d, nil
	}
	if s.Kind == KindWin && s.ReferenceExternalID == "" {
		if f.ReferenceCandidates == 0 {
			return reject(FailReferenceNotFound)
		}
		if f.ReferenceCandidates != 1 || r == nil {
			return reject(FailReferenceMismatch)
		}
	}
	if r != nil {
		if r.ID == s.ID || r.ProviderID != s.ProviderID || r.WalletID != s.WalletID || r.PlayerID != s.PlayerID || r.Amount.Currency() != s.Amount.Currency() || r.RoundID != s.RoundID {
			return reject(FailReferenceMismatch)
		}
		if !CanReference(s.Kind, r.Kind) {
			return reject(FailInvalidReferenceKind)
		}
		if !r.Status.IsTerminal() {
			d.Wait = true
			return d, nil
		}
		if r.Status != StatusProcessed {
			return reject(FailReferenceNotProcessed)
		}
		if s.Kind.IsReversal() && s.Amount.Minor() != r.Amount.Minor() {
			return reject(FailReversalAmountMismatch)
		}
		if s.Kind.IsReversal() && f.AlreadyReversed {
			return reject(FailAlreadyReversed)
		}
		d.ReferenceID = r.ID
	}
	switch s.Kind {
	case KindBet:
		if f.BetID != "" && f.BetStatus != "OPEN" {
			return reject(FailBetClosed)
		}
		d.GuaranteeDirection = Debit
		d.NewCommitment = true
	case KindWin, KindRefund:
		d.GuaranteeDirection = Credit
	case KindRollback:
		if r == nil {
			return d, invalid("rollback reference missing")
		}
		if r.Kind == KindBet {
			d.GuaranteeDirection = Credit
		} else {
			if f.ReferenceSettlementID != "" || f.BetStatus == "CLOSED" {
				return reject(FailConflictingReversal)
			}
			d.GuaranteeDirection = Debit
			d.Restores = f.Restores
		}
		d.ReverseJournalID = f.OriginalJournalID
	case KindLoss:
		return d, nil
	default:
		return d, invalid("unsupported accounting operation")
	}
	insufficient := FailInsufficientFunds
	if s.Kind.IsReversal() {
		insufficient = FailReversalInsufficientFunds
	}
	if d.GuaranteeDirection == Credit {
		if f.BetStatus == "CLOSED" {
			return reject(FailBetClosed)
		}
		if f.BetStatus != "OPEN" || f.CommitmentID == "" || f.Remaining < s.Amount.Minor() {
			return reject(insufficient)
		}
		d.ConsumeCommitmentID = f.CommitmentID
	}
	if s.Kind == KindRefund {
		d.ReverseJournalID = f.OriginalJournalID
	}
	g, err := wallet.Rehydrate(f.Guarantee)
	if err != nil {
		return d, err
	}
	op, err := wallet.Rehydrate(f.Operational)
	if err != nil {
		return d, err
	}
	debit, credit := g, op
	if d.GuaranteeDirection == Credit {
		debit, credit = op, g
	}
	if _, _, err = debit.Debit(s.Amount, now); errors.Is(err, wallet.ErrInsufficientFunds) {
		return reject(insufficient)
	} else if err != nil {
		return d, err
	}
	if _, _, err = credit.Credit(s.Amount, now); errors.Is(err, money.ErrOverflow) {
		return reject(FailureCode("BALANCE_OVERFLOW"))
	} else if err != nil {
		return d, err
	}
	d.Guarantee, d.Operational = g.Snapshot(), op.Snapshot()
	return d, nil
}

internal/domain/wager/errors.go:
package wager

import (
	"errors"
	"fmt"
)

// FailureCode is a stable, documented code persisted in REJECTED/FAILED transactions.
type FailureCode string

const (
	FailBetClosed                 FailureCode = "BET_CLOSED"
	FailInvalidInput              FailureCode = "INVALID_INPUT"
	FailWalletNotFound            FailureCode = "WALLET_NOT_FOUND"
	FailCurrencyMismatch          FailureCode = "CURRENCY_MISMATCH"
	FailInsufficientFunds         FailureCode = "INSUFFICIENT_FUNDS"          // BET without balance
	FailReversalInsufficientFunds FailureCode = "REVERSAL_INSUFFICIENT_FUNDS" // ROLLBACK/REFUND needing more than available
	FailReferenceNotFound         FailureCode = "REFERENCE_NOT_FOUND"         // attempts/TTL exhausted
	FailReferenceNotProcessed     FailureCode = "REFERENCE_NOT_PROCESSED"     // reference exists but ended REJECTED/FAILED
	FailReferenceMismatch         FailureCode = "REFERENCE_MISMATCH"          // provider/player/wallet/currency/round differ
	FailReversalAmountMismatch    FailureCode = "REVERSAL_AMOUNT_MISMATCH"
	FailInvalidReferenceKind      FailureCode = "INVALID_REFERENCE_KIND"
	FailAlreadyReversed           FailureCode = "ALREADY_REVERSED"
	FailConflictingReversal       FailureCode = "CONFLICTING_REVERSAL" // REFUND x ROLLBACK on same bet (see ARCHITECTURE.md)
	FailInternalPermanent         FailureCode = "INTERNAL_PERMANENT_ERROR"
)

type DomainError struct {
	Code FailureCode
	Msg  string
}

func (e *DomainError) Error() string { return string(e.Code) + ": " + e.Msg }

// Is compares by code so wrapped errors match sentinels via errors.Is.
func (e *DomainError) Is(target error) bool {
	t, ok := target.(*DomainError)
	return ok && t.Code == e.Code
}

func newErr(c FailureCode, msg string) *DomainError { return &DomainError{c, msg} }

var (
	ErrInvalidInput           = newErr(FailInvalidInput, "invalid input")
	ErrInsufficientFunds      = newErr(FailInsufficientFunds, "insufficient funds")
	ErrReversalInsufficient   = newErr(FailReversalInsufficientFunds, "insufficient funds to reverse")
	ErrReferenceNotFound      = newErr(FailReferenceNotFound, "reference not found")
	ErrReferenceNotProcessed  = newErr(FailReferenceNotProcessed, "reference not processed")
	ErrReferenceMismatch      = newErr(FailReferenceMismatch, "reference mismatch")
	ErrReversalAmountMismatch = newErr(FailReversalAmountMismatch, "reversal amount mismatch")
	ErrInvalidReferenceKind   = newErr(FailInvalidReferenceKind, "invalid reference kind")
	ErrAlreadyReversed        = newErr(FailAlreadyReversed, "already reversed")
	ErrConflictingReversal    = newErr(FailConflictingReversal, "conflicting reversal")

	ErrTerminalState = errors.New("wager: transaction is in a terminal state")
)

// CodeOf extracts the failure code of a (possibly wrapped) DomainError.
func CodeOf(err error) (FailureCode, bool) {
	var d *DomainError
	if errors.As(err, &d) {
		return d.Code, true
	}
	return "", false
}

func invalid(format string, a ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidInput, fmt.Sprintf(format, a...))
}

