package wager

import (
	"time"

	"github.com/alexandre/wagering/internal/domain/money"
)

// LedgerEntry is immutable; construction validates balanceAfter = balanceBefore ± amount.
type LedgerEntry struct {
	id, walletID, transactionID string
	direction                   Direction
	amount, before, after       money.Money
	createdAt                   time.Time
}

func NewLedgerEntry(id, walletID, txID string, dir Direction, amount, before money.Money, now time.Time) (LedgerEntry, error) {
	if now.IsZero() || before.IsNegative() || id == "" || walletID == "" || txID == "" {
		return LedgerEntry{}, invalid("ledger entry ids are required")
	}
	if !amount.IsPositive() {
		return LedgerEntry{}, invalid("ledger amount must be positive")
	}
	var (
		after money.Money
		err   error
	)
	switch dir {
	case Debit:
		after, err = before.Sub(amount)
	case Credit:
		after, err = before.Add(amount)
	default:
		return LedgerEntry{}, invalid("unknown direction %q", dir)
	}
	if err != nil {
		return LedgerEntry{}, err
	}
	if after.IsNegative() {
		return LedgerEntry{}, ErrInsufficientFunds
	}
	return LedgerEntry{id, walletID, txID, dir, amount, before, after, now}, nil
}

// RehydrateLedgerEntry validates the stored math instead of trusting it.
func RehydrateLedgerEntry(id, walletID, txID string, dir Direction, amount, before, after money.Money, at time.Time) (LedgerEntry, error) {
	e, err := NewLedgerEntry(id, walletID, txID, dir, amount, before, at)
	if err != nil {
		return LedgerEntry{}, err
	}
	if c, err := e.after.Cmp(after); err != nil || c != 0 {
		return LedgerEntry{}, invalid("ledger entry %s has inconsistent balances", id)
	}
	return e, nil
}

func (e LedgerEntry) ID() string                 { return e.id }
func (e LedgerEntry) WalletID() string           { return e.walletID }
func (e LedgerEntry) TransactionID() string      { return e.transactionID }
func (e LedgerEntry) Direction() Direction       { return e.direction }
func (e LedgerEntry) Amount() money.Money        { return e.amount }
func (e LedgerEntry) BalanceBefore() money.Money { return e.before }
func (e LedgerEntry) BalanceAfter() money.Money  { return e.after }
func (e LedgerEntry) CreatedAt() time.Time       { return e.createdAt }

internal/domain/wager/rules.go:
package wager

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"

	"github.com/alexandre/wagering/internal/domain/money"
)

// MovementFor returns the wallet movement of a non-reversal kind (ok=false → no movement, e.g. LOSS).
func MovementFor(k Kind) (dir Direction, ok bool) {
	switch k {
	case KindBet:
		return Debit, true
	case KindWin, KindRefund, KindOpening:
		return Credit, true
	}
	return "", false
}

// CanReference reports whether op may reference a processed transaction of kind ref.
func CanReference(op, ref Kind) bool {
	switch op {
	case KindRefund:
		return ref == KindBet
	case KindRollback:
		return ref == KindBet || ref == KindWin || ref == KindRefund
	case KindWin:
		return ref == KindBet
	}
	return false
}

// ReversalDirection is the opposite of the original movement (used by ROLLBACK).
func ReversalDirection(original Kind) (Direction, error) {
	d, ok := MovementFor(original)
	if !ok || original == KindOpening {
		return "", ErrInvalidReferenceKind
	}
	if d == Debit {
		return Credit, nil
	}
	return Debit, nil
}

func validateAmount(k Kind, m money.Money) error {
	if m.Currency() == "" {
		return invalid("money is not initialized")
	}
	switch k {
	case KindLoss:
		if !m.IsZero() {
			return invalid("LOSS requires amount 0.00")
		}
	default:
		if !m.IsPositive() {
			return invalid("%s requires amount greater than zero", k)
		}
	}
	return nil
}

// HashInput lists the business fields covered by the idempotency hash. It is shared by HTTP and SQS.
// The idempotency key and transport metadata are deliberately excluded.
type HashInput struct {
	BetID                                                                  string
	ProviderID, ExternalTransactionID, PlayerID, WalletID, RoundID, GameID string
	Kind, ReferenceExternalTransactionID                                   string
	Amount, Currency                                                       string // amount already normalized ("25.00")
}

// PayloadHash = hex(sha256(canonical JSON)); map marshaling sorts keys, giving canonical ordering.
func PayloadHash(in HashInput) string {
	m := map[string]any{
		"providerId":            in.ProviderID,
		"externalTransactionId": in.ExternalTransactionID,
		"playerId":              in.PlayerID,
		"walletId":              in.WalletID,
		"roundId":               in.RoundID,
		"gameId":                in.GameID,
		"kind":                  in.Kind,
		"money":                 map[string]any{"amount": in.Amount, "currency": in.Currency},
	}
	if in.BetID != "" {
		m["betId"] = in.BetID
	}
	if in.ReferenceExternalTransactionID != "" {
		m["referenceExternalTransactionId"] = in.ReferenceExternalTransactionID
	}
	b, _ := json.Marshal(m)
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

internal/domain/wager/transaction.go:
// Package wager holds WagerTransaction (state machine), WalletLedgerEntry and per-kind rules.
package wager

import (
	"math"
	"time"

	"github.com/alexandre/wagering/internal/domain/money"
)

type Transaction struct {
	correlationID, causationID                          string
	id                                                  string
	origin                                              Origin
	providerID, externalID, idempotencyKey, payloadHash string
	walletID, playerID, roundID, gameID                 string
	kind                                                Kind
	amount                                              money.Money
	referenceExternalID, referenceID                    string
	status                                              Status
	failureCode                                         FailureCode
	balanceAfter                                        *money.Money
	attempts                                            int
	nextAttemptAt, expiresAt                            *time.Time
	createdAt, updatedAt                                time.Time
}

// Snapshot is the persistence view (repositories map rows <-> Snapshot).
type Snapshot struct {
	CorrelationID, CausationID                          string
	ID                                                  string
	Origin                                              Origin
	ProviderID, ExternalID, IdempotencyKey, PayloadHash string
	WalletID, PlayerID, RoundID, GameID                 string
	Kind                                                Kind
	Amount                                              money.Money
	ReferenceExternalID, ReferenceID                    string
	Status                                              Status
	FailureCode                                         FailureCode
	BalanceAfter                                        *money.Money
	Attempts                                            int
	NextAttemptAt, ExpiresAt                            *time.Time
	CreatedAt, UpdatedAt                                time.Time
}

type ExternalParams struct {
	CorrelationID, CausationID                              string
	ID, ProviderID, ExternalID, IdempotencyKey, PayloadHash string
	WalletID, PlayerID, RoundID, GameID                     string
	Kind                                                    Kind
	Amount                                                  money.Money
	ReferenceExternalID                                     string
}

// NewExternal creates an accepted external operation in PENDING.
func NewExternal(p ExternalParams, now time.Time) (*Transaction, error) {
	if now.IsZero() {
		return nil, invalid("timestamp required")
	}
	for name, v := range map[string]string{
		"id": p.ID, "providerId": p.ProviderID, "externalTransactionId": p.ExternalID,
		"idempotencyKey": p.IdempotencyKey, "payloadHash": p.PayloadHash, "walletId": p.WalletID,
		"playerId": p.PlayerID, "roundId": p.RoundID, "gameId": p.GameID,
	} {
		if v == "" {
			return nil, invalid("%s is required", name)
		}
	}
	if _, err := ParseExternalKind(string(p.Kind)); err != nil {
		return nil, err
	}
	if err := validateAmount(p.Kind, p.Amount); err != nil {
		return nil, err
	}
	if p.Kind.IsReversal() && p.ReferenceExternalID == "" {
		return nil, invalid("referenceExternalTransactionId is required for %s", p.Kind)
	}
	if !p.Kind.IsReversal() && p.Kind != KindWin && p.ReferenceExternalID != "" {
		return nil, invalid("%s must not carry a reference", p.Kind)
	}
	return &Transaction{
		correlationID: p.CorrelationID, causationID: p.CausationID, id: p.ID, origin: OriginExternal, providerID: p.ProviderID, externalID: p.ExternalID,
		idempotencyKey: p.IdempotencyKey, payloadHash: p.PayloadHash, walletID: p.WalletID,
		playerID: p.PlayerID, roundID: p.RoundID, gameID: p.GameID, kind: p.Kind, amount: p.Amount,
		referenceExternalID: p.ReferenceExternalID, status: StatusPending, createdAt: now, updatedAt: now,
	}, nil
}

// NewOpening creates the internal wallet-opening credit (already PROCESSED). Zero amounts create no OPENING.
func NewOpening(id, walletID, playerID string, amount money.Money, now time.Time) (*Transaction, error) {
	if now.IsZero() || id == "" || walletID == "" || playerID == "" {
		return nil, invalid("id, walletId and playerId are required")
	}
	if !amount.IsPositive() {
		return nil, invalid("OPENING requires a positive amount")
	}
	after := amount
	return &Transaction{
		id: id, origin: OriginInternal, walletID: walletID, playerID: playerID, kind: KindOpening,
		amount: amount, status: StatusProcessed, balanceAfter: &after, createdAt: now, updatedAt: now,
	}, nil
}

// Rehydrate rebuilds a transaction from storage without reapplying anything.
func Rehydrate(s Snapshot) (*Transaction, error) {
	if s.ID == "" || s.WalletID == "" || !s.Status.Valid() || s.Amount.Currency() == "" {
		return nil, invalid("corrupted snapshot %q", s.ID)
	}
	if (s.Origin == OriginInternal) != (s.Kind == KindOpening) {
		return nil, invalid("origin/kind mismatch in snapshot %q", s.ID)
	}
	if s.Origin != OriginInternal && s.Origin != OriginExternal {
		return nil, invalid("invalid origin")
	}
	if s.PlayerID == "" || s.CreatedAt.IsZero() || s.UpdatedAt.IsZero() || s.UpdatedAt.Before(s.CreatedAt) || s.Attempts < 0 {
		return nil, invalid("invalid snapshot")
	}
	if s.Origin == OriginExternal {
		if _, err := NewExternal(ExternalParams{ID: s.ID, ProviderID: s.ProviderID, ExternalID: s.ExternalID, IdempotencyKey: s.IdempotencyKey, PayloadHash: s.PayloadHash, WalletID: s.WalletID, PlayerID: s.PlayerID, RoundID: s.RoundID, GameID: s.GameID, Kind: s.Kind, Amount: s.Amount, ReferenceExternalID: s.ReferenceExternalID}, s.CreatedAt); err != nil {
			return nil, err
		}
	} else if !s.Amount.IsPositive() || s.Status != StatusProcessed || s.ProviderID != "" || s.ExternalID != "" || s.IdempotencyKey != "" || s.PayloadHash != "" || s.RoundID != "" || s.GameID != "" || s.ReferenceExternalID != "" || s.ReferenceID != "" {
		return nil, invalid("invalid opening snapshot")
	}
	if s.Status == StatusProcessed && (s.BalanceAfter == nil || s.BalanceAfter.Currency() != s.Amount.Currency() || s.BalanceAfter.IsNegative() || s.FailureCode != "") {
		return nil, invalid("invalid processed snapshot")
	}
	if (s.Status == StatusRejected || s.Status == StatusFailed) && s.FailureCode == "" {
		return nil, invalid("missing failure")
	}
	if s.Status == StatusPendingReference && (s.NextAttemptAt == nil || s.ExpiresAt == nil || s.ReferenceExternalID == "") {
		return nil, invalid("invalid pending reference")
	}
	// State shape is checked independently of persistence: a snapshot must be
	// reachable through the public transitions without inventing financial facts.
	if s.ReferenceID != "" && ((s.ReferenceExternalID == "" && s.Kind != KindWin) || s.ReferenceID == s.ID) {
		return nil, invalid("invalid resolved reference")
	}
	if s.Status == StatusProcessed && (s.ReferenceExternalID != "" || s.Kind == KindWin) && s.ReferenceID == "" {
		return nil, invalid("processed reference not resolved")
	}
	if s.Status != StatusProcessed && s.BalanceAfter != nil {
		return nil, invalid("result on unprocessed transaction")
	}
	if !s.Status.IsTerminal() && s.FailureCode != "" {
		return nil, invalid("failure on open transaction")
	}
	if s.Status != StatusPendingReference && s.NextAttemptAt != nil {
		return nil, invalid("schedule outside pending reference")
	}
	if s.Status == StatusPending && (s.Attempts != 0 || s.ExpiresAt != nil) {
		return nil, invalid("retry history on initial pending state")
	}
	if s.Status == StatusPendingReference && (s.Attempts == 0 || !s.NextAttemptAt.After(s.UpdatedAt)) {
		return nil, invalid("invalid reference attempt")
	}
	if (s.Attempts > 0) != (s.ExpiresAt != nil) || (s.ExpiresAt != nil && (!s.ExpiresAt.After(s.CreatedAt) || s.ReferenceExternalID == "")) {
		return nil, invalid("invalid reference lifetime")
	}
	if s.Kind == KindOpening && (s.BalanceAfter == nil || s.BalanceAfter.Minor() != s.Amount.Minor() || s.Attempts != 0) {
		return nil, invalid("invalid opening result")
	}
	return &Transaction{
		correlationID: s.CorrelationID, causationID: s.CausationID, id: s.ID, origin: s.Origin, providerID: s.ProviderID, externalID: s.ExternalID,
		idempotencyKey: s.IdempotencyKey, payloadHash: s.PayloadHash, walletID: s.WalletID,
		playerID: s.PlayerID, roundID: s.RoundID, gameID: s.GameID, kind: s.Kind, amount: s.Amount,
		referenceExternalID: s.ReferenceExternalID, referenceID: s.ReferenceID, status: s.Status,
		failureCode: s.FailureCode, balanceAfter: copyMoney(s.BalanceAfter), attempts: s.Attempts,
		nextAttemptAt: copyTime(s.NextAttemptAt), expiresAt: copyTime(s.ExpiresAt), createdAt: s.CreatedAt, updatedAt: s.UpdatedAt,
	}, nil
}

func (t *Transaction) Snapshot() Snapshot {
	return Snapshot{
		t.correlationID, t.causationID, t.id, t.origin, t.providerID, t.externalID, t.idempotencyKey, t.payloadHash,
		t.walletID, t.playerID, t.roundID, t.gameID, t.kind, t.amount,
		t.referenceExternalID, t.referenceID, t.status, t.failureCode, copyMoney(t.balanceAfter),
		t.attempts, copyTime(t.nextAttemptAt), copyTime(t.expiresAt), t.createdAt, t.updatedAt,
	}
}

func (t *Transaction) ID() string                  { return t.id }
func (t *Transaction) Status() Status              { return t.status }
func (t *Transaction) Kind() Kind                  { return t.kind }
func (t *Transaction) Amount() money.Money         { return t.amount }
func (t *Transaction) WalletID() string            { return t.walletID }
func (t *Transaction) ReferenceExternalID() string { return t.referenceExternalID }
func (t *Transaction) ReferenceID() string         { return t.referenceID }
func (t *Transaction) FailureCode() FailureCode    { return t.failureCode }

func (t *Transaction) ensureOpen() error {
	if t == nil || t.id == "" || !t.status.Valid() {
		return invalid("uninitialized transaction")
	}
	if t.status.IsTerminal() {
		return ErrTerminalState
	}
	return nil
}

// ResolveReference links the internal id of the referenced transaction.
func (t *Transaction) ResolveReference(refID string) error {
	if err := t.ensureOpen(); err != nil {
		return err
	}
	if refID == "" || refID == t.id || (t.referenceExternalID == "" && t.kind != KindWin) || (t.referenceID != "" && t.referenceID != refID) {
		return invalid("invalid reference")
	}
	t.referenceID = refID
	return nil
}

// MarkPendingReference parks the operation until its reference arrives (backoff/TTL handled by the caller).
func (t *Transaction) MarkPendingReference(now, nextAttempt time.Time, ttl time.Duration) error {
	if err := t.ensureOpen(); err != nil {
		return err
	}
	if now.IsZero() || now.Before(t.updatedAt) || !nextAttempt.After(now) || ttl <= 0 || t.attempts == math.MaxInt {
		return invalid("invalid reference schedule")
	}
	if t.referenceExternalID == "" {
		return invalid("transaction has no reference to wait for")
	}
	t.status = StatusPendingReference
	t.attempts++
	if t.expiresAt == nil {
		e := now.Add(ttl)
		t.expiresAt = &e
	}
	t.nextAttemptAt = &nextAttempt
	t.updatedAt = now
	return nil
}

func (t *Transaction) ReferenceExpired(now time.Time) bool {
	return t.expiresAt != nil && !now.Before(*t.expiresAt)
}

// MarkProcessed stores the balance observed at processing time (returned verbatim on replays).
func (t *Transaction) MarkProcessed(balanceAfter money.Money, now time.Time) error {
	if now.IsZero() || (t != nil && now.Before(t.updatedAt)) {
		return invalid("invalid transition timestamp")
	}
	if err := t.ensureOpen(); err != nil {
		return err
	}
	if (t.referenceExternalID != "" || t.kind == KindWin) && t.referenceID == "" {
		return invalid("reference not resolved")
	}
	if balanceAfter.Currency() != t.amount.Currency() || balanceAfter.IsNegative() {
		return invalid("invalid result balance")
	}
	t.status, t.balanceAfter, t.nextAttemptAt, t.updatedAt = StatusProcessed, &balanceAfter, nil, now
	return nil
}

func (t *Transaction) Reject(code FailureCode, now time.Time) error {
	if now.IsZero() || (t != nil && now.Before(t.updatedAt)) {
		return invalid("invalid transition timestamp")
	}
	if err := t.ensureOpen(); err != nil {
		return err
	}
	if code == "" {
		return invalid("failure code required")
	}
	t.status, t.failureCode, t.nextAttemptAt, t.updatedAt = StatusRejected, code, nil, now
	return nil
}

// Fail records a permanent infrastructure failure for audit.
func (t *Transaction) Fail(code FailureCode, now time.Time) error {
	if now.IsZero() || (t != nil && now.Before(t.updatedAt)) {
		return invalid("invalid transition timestamp")
	}
	if err := t.ensureOpen(); err != nil {
		return err
	}
	if code == "" {
		return invalid("failure code required")
	}
	t.status, t.failureCode, t.nextAttemptAt, t.updatedAt = StatusFailed, code, nil, now
	return nil
}

func copyMoney(m *money.Money) *money.Money {
	if m == nil {
		return nil
	}
	v := *m
	return &v
}
func copyTime(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	v := *t
	return &v
}

internal/domain/wager/types.go:
package wager

type Kind string

const (
	KindOpening  Kind = "OPENING"
	KindBet      Kind = "BET"
	KindWin      Kind = "WIN"
	KindLoss     Kind = "LOSS"
	KindRefund   Kind = "REFUND"
	KindRollback Kind = "ROLLBACK"
)

// ParseExternalKind accepts only kinds allowed via HTTP/SQS (OPENING is internal-only).
func ParseExternalKind(s string) (Kind, error) {
	switch k := Kind(s); k {
	case KindBet, KindWin, KindLoss, KindRefund, KindRollback:
		return k, nil
	case KindOpening:
		return "", invalid("OPENING is reserved for internal wallet opening")
	default:
		return "", invalid("unknown kind %q", s)
	}
}

func (k Kind) IsReversal() bool { return k == KindRefund || k == KindRollback }

type Status string

const (
	StatusPending          Status = "PENDING"
	StatusPendingReference Status = "PENDING_REFERENCE"
	StatusProcessed        Status = "PROCESSED"
	StatusRejected         Status = "REJECTED"
	StatusFailed           Status = "FAILED"
)

func (s Status) IsTerminal() bool {
	return s == StatusProcessed || s == StatusRejected || s == StatusFailed
}

func (s Status) Valid() bool {
	switch s {
	case StatusPending, StatusPendingReference, StatusProcessed, StatusRejected, StatusFailed:
		return true
	}
	return false
}

type Origin string

const (
	OriginInternal Origin = "INTERNAL"
	OriginExternal Origin = "EXTERNAL"
)

type Direction string

const (
	Debit  Direction = "DEBIT"
	Credit Direction = "CREDIT"
)

internal/domain/wallet/wallet.go:
// Package wallet holds the Wallet aggregate root. It is independent of Fx, HTTP, SQS and DB libs.
package wallet

import (
	"errors"
	"math"
	"time"

	"github.com/alexandre/wagering/internal/domain/money"
)

var (
	ErrInvalidWallet     = errors.New("wallet: invalid")
	ErrInsufficientFunds = errors.New("wallet: insufficient funds")
	ErrNonPositiveAmount = errors.New("wallet: amount must be positive")
)

type Wallet struct {
	id, playerID         string
	balance              money.Money
	version              int64
	createdAt, updatedAt time.Time
}

// Snapshot is the persistence view of a Wallet (used by repositories to map rows).
type Snapshot struct {
	ID, PlayerID         string
	Balance              money.Money
	Version              int64
	CreatedAt, UpdatedAt time.Time
}

// New creates a wallet with version 1 (initial balance may be zero).
func New(id, playerID string, initial money.Money, now time.Time) (*Wallet, error) {
	if now.IsZero() || id == "" || playerID == "" || initial.Currency() == "" || initial.IsNegative() {
		return nil, ErrInvalidWallet
	}
	return &Wallet{id: id, playerID: playerID, balance: initial, version: 1, createdAt: now, updatedAt: now}, nil
}

// Rehydrate rebuilds a wallet from storage WITHOUT reapplying movements or emitting events.
func Rehydrate(s Snapshot) (*Wallet, error) {
	if s.CreatedAt.IsZero() || s.UpdatedAt.Before(s.CreatedAt) || s.ID == "" || s.PlayerID == "" || s.Balance.Currency() == "" || s.Balance.IsNegative() || s.Version < 1 {
		return nil, ErrInvalidWallet
	}
	return &Wallet{s.ID, s.PlayerID, s.Balance, s.Version, s.CreatedAt, s.UpdatedAt}, nil
}

func (w *Wallet) Snapshot() Snapshot {
	return Snapshot{w.id, w.playerID, w.balance, w.version, w.createdAt, w.updatedAt}
}
func (w *Wallet) ID() string           { return w.id }
func (w *Wallet) PlayerID() string     { return w.playerID }
func (w *Wallet) Balance() money.Money { return w.balance }
func (w *Wallet) Version() int64       { return w.version }
func (w *Wallet) Currency() string     { return w.balance.Currency() }

func (w *Wallet) check(m money.Money) error {
	if w == nil || w.id == "" || w.version < 1 || w.balance.Currency() == "" {
		return ErrInvalidWallet
	}
	if w.version == math.MaxInt64 {
		return money.ErrOverflow
	}
	if m.Currency() == "" {
		return money.ErrUninitialized
	}
	if m.Currency() != w.balance.Currency() {
		return money.ErrCurrencyMismatch
	}
	if !m.IsPositive() {
		return ErrNonPositiveAmount
	}
	return nil
}

// Debit removes m from the balance; the balance can never go below zero.
func (w *Wallet) Debit(m money.Money, now time.Time) (before, after money.Money, err error) {
	if err = w.check(m); err != nil {
		return
	}
	if now.IsZero() || now.Before(w.updatedAt) {
		return money.Money{}, money.Money{}, ErrInvalidWallet
	}
	before = w.balance
	// check guarantees initialized money of the same currency. Comparing minor
	// units is exact and cannot fail.
	if before.Minor() < m.Minor() {
		return money.Money{}, money.Money{}, ErrInsufficientFunds
	}
	// Both operands are nonnegative, with before >= m: subtraction cannot
	// overflow or produce a negative balance after the checks above.
	after, _ = before.Sub(m)
	w.apply(after, now)
	return before, after, nil
}

func (w *Wallet) Credit(m money.Money, now time.Time) (before, after money.Money, err error) {
	if err = w.check(m); err != nil {
		return
	}
	if now.IsZero() || now.Before(w.updatedAt) {
		return money.Money{}, money.Money{}, ErrInvalidWallet
	}
	before = w.balance
	if after, err = w.balance.Add(m); err != nil {
		return
	}
	w.apply(after, now)
	return before, after, nil
}

// apply bumps the version ONLY when the balance changes.
func (w *Wallet) apply(after money.Money, now time.Time) {
	w.balance = after
	w.version++
	w.updatedAt = now
}

internal/infra/auth/middleware.go:
package auth

import (
	"context"
	"errors"
	"net/http"
	"strings"
)

type ctxKey struct{}

func PrincipalFrom(ctx context.Context) (Principal, bool) {
	p, ok := ctx.Value(ctxKey{}).(Principal)
	return p, ok
}

func deny(w http.ResponseWriter, status int, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write([]byte(`{"code":"` + code + `"}`))
}

// Authenticate requires a valid Bearer token (401 missing/invalid/expired; 503 if the IdP is unreachable).
func (v *Verifier) Authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		tok, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		if !ok || tok == "" {
			deny(w, http.StatusUnauthorized, "UNAUTHENTICATED")
			return
		}
		p, err := v.Verify(r.Context(), tok)
		if err != nil {
			if errors.Is(err, ErrJWKSUnavailable) {
				w.Header().Set("Retry-After", "2")
				deny(w, http.StatusServiceUnavailable, "IDP_UNAVAILABLE")
				return
			}
			deny(w, http.StatusUnauthorized, "UNAUTHENTICATED")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, p)))
	})
}

// RequireInternal restricts wallet operations to the internal service.
func RequireInternal(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if p, ok := PrincipalFrom(r.Context()); !ok || !p.Internal {
			deny(w, http.StatusForbidden, "FORBIDDEN")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// RequireProvider requires a provider identity (providerId claim).
func RequireProvider(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if p, ok := PrincipalFrom(r.Context()); !ok || p.ProviderID == "" {
			deny(w, http.StatusForbidden, "FORBIDDEN")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// RequireProviderOrInternal is used by read endpoints (scoping is enforced in the use case).
func RequireProviderOrInternal(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if p, ok := PrincipalFrom(r.Context()); !ok || (p.ProviderID == "" && !p.Internal) {
			deny(w, http.StatusForbidden, "FORBIDDEN")
			return
		}
		next.ServeHTTP(w, r)
	})
}

internal/infra/auth/verifier.go:
// Package auth validates externally issued OIDC tokens with a bounded JWKS cache.
package auth

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"sync"
	"time"

	"github.com/MicahParks/jwkset"
	"github.com/MicahParks/keyfunc/v3"
	"github.com/alexandre/wagering/internal/infra/config"
	"github.com/golang-jwt/jwt/v5"
	"go.uber.org/fx"
)

var (
	ErrJWKSUnavailable = errors.New("auth: jwks unavailable")
	ErrInvalidToken    = errors.New("auth: invalid token")
)

type Principal struct {
	Subject, ProviderID string
	Internal            bool
}

// Refresh is request-owned: no background goroutine can outlive the application.
// Cached keys live for one hour; an unknown kid can trigger at most one fetch/second.
type Verifier struct {
	issuer, jwksURL, audience string
	client                    *http.Client
	gate                      chan struct{}
	mu                        sync.RWMutex
	kf                        keyfunc.Keyfunc
	fetched, attempted        time.Time
	lastErr                   error
	now                       func() time.Time // immutable source for cache-age decisions; deadlines use context
}

func NewVerifier(lc fx.Lifecycle, cfg config.Config) *Verifier {
	v := &Verifier{now: time.Now, issuer: cfg.OIDCIssuer, jwksURL: cfg.OIDCJWKSURL, audience: cfg.OIDCAudience,
		client: &http.Client{Timeout: 2 * time.Second, Transport: http.DefaultTransport.(*http.Transport).Clone()}, gate: make(chan struct{}, 1)}
	lc.Append(fx.Hook{OnStart: func(ctx context.Context) error {
		err := v.refresh(ctx, true)
		if err != nil {
			v.client.CloseIdleConnections()
		}
		return err
	}, OnStop: func(context.Context) error { v.client.CloseIdleConnections(); return nil }})
	return v
}

func (v *Verifier) refresh(ctx context.Context, initial bool) error {
	select {
	case v.gate <- struct{}{}:
	case <-ctx.Done():
		return fmt.Errorf("%w: %w", ErrJWKSUnavailable, ctx.Err())
	}
	defer func() { <-v.gate }()
	v.mu.RLock()
	recent := v.now().Sub(v.attempted) < time.Second
	last := v.lastErr
	v.mu.RUnlock()
	if recent && !initial {
		return last
	}
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, v.jwksURL, nil)
	var kf keyfunc.Keyfunc
	if err == nil {
		var res *http.Response
		res, err = v.client.Do(req)
		if err == nil {
			defer res.Body.Close()
			if res.StatusCode != http.StatusOK {
				err = fmt.Errorf("JWKS HTTP status %d", res.StatusCode)
			} else {
				var body []byte
				body, err = io.ReadAll(io.LimitReader(res.Body, 1<<20))
				if err == nil {
					kf, err = keyfunc.NewJWKSetJSON(body)
				}
				if err == nil {
					keys, e := kf.Storage().KeyReadAll(ctx)
					err = e
					if err == nil && len(keys) == 0 {
						err = errors.New("empty JWKS")
					}
				}
			}
		}
	}
	if err != nil {
		err = fmt.Errorf("%w: %w", ErrJWKSUnavailable, err)
	}
	v.mu.Lock()
	defer v.mu.Unlock()
	v.attempted = v.now()
	v.lastErr = err
	if err == nil {
		v.kf = kf
		v.fetched = v.attempted
	}
	return err
}

func (v *Verifier) key(ctx context.Context, t *jwt.Token) (any, error) {
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("%w: %w", ErrJWKSUnavailable, err)
	}
	kid, ok := t.Header["kid"].(string)
	if !ok || kid == "" {
		return nil, ErrInvalidToken
	}
	v.mu.RLock()
	kf, fetched := v.kf, v.fetched
	v.mu.RUnlock()
	if kf != nil && v.now().Sub(fetched) < time.Hour {
		key, err := kf.KeyfuncCtx(ctx)(t)
		if !errors.Is(err, jwkset.ErrKeyNotFound) {
			return key, err
		}
	}
	if err := v.refresh(ctx, false); err != nil {
		return nil, err
	}
	v.mu.RLock()
	kf, fetched = v.kf, v.fetched
	v.mu.RUnlock()
	if kf == nil || v.now().Sub(fetched) >= time.Hour {
		return nil, ErrJWKSUnavailable
	}
	return kf.KeyfuncCtx(ctx)(t)
}

func (v *Verifier) Verify(ctx context.Context, raw string) (Principal, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	claims := jwt.MapClaims{}
	_, err := jwt.ParseWithClaims(raw, claims, func(t *jwt.Token) (any, error) { return v.key(ctx, t) },
		jwt.WithValidMethods([]string{"RS256"}), jwt.WithIssuer(v.issuer), jwt.WithAudience(v.audience), jwt.WithExpirationRequired())
	if err != nil {
		if errors.Is(err, ErrJWKSUnavailable) {
			return Principal{}, err
		}
		return Principal{}, fmt.Errorf("%w: %w", ErrInvalidToken, err)
	}
	sub, _ := claims.GetSubject()
	if sub == "" {
		return Principal{}, ErrInvalidToken
	}
	p := Principal{Subject: sub}
	p.ProviderID, _ = claims["providerId"].(string)
	role, _ := claims["role"].(string)
	p.Internal = role == "internal"
	return p, nil
}

var Module = fx.Module("auth", fx.Provide(NewVerifier))

internal/infra/config/config.go:
package config

import (
	"errors"
	"fmt"
	"os"
	"strings"
	"time"
)

type Config struct {
	Roles              []string
	HTTPAddr           string
	ShutdownTimeout    time.Duration
	LogLevel           string
	DatabaseURL        string
	AWSRegion          string
	AWSEndpointURL     string
	WagerQueueURL      string
	WagerDLQURL        string
	EventsQueueURL     string
	SettlementQueueURL string
	OIDCIssuer         string
	OIDCJWKSURL        string
	OIDCAudience       string
}

func (c Config) HasRole(r string) bool {
	for _, x := range c.Roles {
		if x == r {
			return true
		}
	}
	return false
}

func env(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

// Load reads and validates configuration from the environment.
func Load() (Config, error) {
	d, err := time.ParseDuration(env("SHUTDOWN_TIMEOUT", "25s"))
	if err != nil {
		return Config{}, fmt.Errorf("SHUTDOWN_TIMEOUT: %w", err)
	}
	c := Config{
		Roles:              strings.Split(env("ROLES", "api"), ","),
		HTTPAddr:           env("HTTP_ADDR", ":8080"),
		ShutdownTimeout:    d,
		LogLevel:           env("LOG_LEVEL", "info"),
		DatabaseURL:        os.Getenv("DATABASE_URL"),
		AWSRegion:          env("AWS_REGION", "us-east-1"),
		AWSEndpointURL:     os.Getenv("AWS_ENDPOINT_URL"),
		WagerQueueURL:      os.Getenv("WAGER_QUEUE_URL"),
		WagerDLQURL:        os.Getenv("WAGER_DLQ_URL"),
		EventsQueueURL:     os.Getenv("EVENTS_QUEUE_URL"),
		SettlementQueueURL: os.Getenv("SETTLEMENT_QUEUE_URL"),
		OIDCIssuer:         os.Getenv("OIDC_ISSUER"),
		OIDCJWKSURL:        os.Getenv("OIDC_JWKS_URL"),
		OIDCAudience:       os.Getenv("OIDC_AUDIENCE"),
	}
	var errs []error
	if d < 8*time.Second || d > 25*time.Second {
		errs = append(errs, errors.New("SHUTDOWN_TIMEOUT must be in [8s,25s]"))
	}
	for _, r := range c.Roles {
		switch r {
		case "api", "sqs-consumer", "outbox-publisher", "reference-worker":
		default:
			errs = append(errs, fmt.Errorf("unknown role %s", r))
		}
	}
	for k, v := range map[string]string{
		"OIDC_AUDIENCE": c.OIDCAudience, "DATABASE_URL": c.DatabaseURL, "OIDC_ISSUER": c.OIDCIssuer, "OIDC_JWKS_URL": c.OIDCJWKSURL,
		"WAGER_QUEUE_URL": c.WagerQueueURL, "EVENTS_QUEUE_URL": c.EventsQueueURL, "SETTLEMENT_QUEUE_URL": c.SettlementQueueURL,
	} {
		if v == "" {
			errs = append(errs, fmt.Errorf("missing required env %s", k))
		}
	}
	return c, errors.Join(errs...)
}

