internal/infra/postgres/inbox_outbox_rep:
package postgres

import (
	"context"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/event"
	"time"
)

type inboxRepo struct{ q dbtx }

func (r inboxRepo) Begin(ctx context.Context, c, id, h string, now time.Time) (port.InboxState, error) {
	_, err := r.q.Exec(ctx, `INSERT INTO inbox_messages(consumer_name,message_id,payload_hash,received_at) VALUES($1,$2,$3,$4) ON CONFLICT(consumer_name,message_id) DO UPDATE SET deliveries=inbox_messages.deliveries+1`, c, id, h, now)
	if err != nil {
		return port.InboxNew, err
	}
	var hash string
	var completed *time.Time
	err = r.q.QueryRow(ctx, `SELECT payload_hash,completed_at FROM inbox_messages WHERE consumer_name=$1 AND message_id=$2 FOR UPDATE`, c, id).Scan(&hash, &completed)
	if err != nil {
		return port.InboxNew, err
	}
	if h != hash {
		return port.InboxConflict, nil
	}
	if completed != nil {
		return port.InboxCompleted, nil
	}
	return port.InboxNew, nil
}
func (r inboxRepo) Complete(ctx context.Context, c, id string, now time.Time) error {
	_, err := r.q.Exec(ctx, `UPDATE inbox_messages SET completed_at=coalesce(completed_at,$3),transaction_id=coalesce(transaction_id,(SELECT id FROM wager_transactions WHERE causation_id=$2 ORDER BY created_at,id LIMIT 1)) WHERE consumer_name=$1 AND message_id=$2`, c, id, now)
	return err
}

type outboxRepo struct{ q dbtx }

func (r outboxRepo) Add(ctx context.Context, e event.Outgoing) error {
	_, err := r.q.Exec(ctx, `INSERT INTO outbox_events(event_id,aggregate_id,event_type,payload,occurred_at,next_attempt_at) VALUES($1,$2,$3,$4,$5,$5)`, e.EventID(), e.AggregateID(), e.Type(), e.Payload(), e.OccurredAt())
	return err
}
func (r outboxRepo) ClaimBatch(ctx context.Context, now time.Time, limit int, lease time.Duration) ([]event.Outgoing, error) {
	rows, err := r.q.Query(ctx, `UPDATE outbox_events SET locked_until=$2, attempts=attempts+1 WHERE event_id IN(SELECT event_id FROM outbox_events WHERE published_at IS NULL AND next_attempt_at<=$1 AND (locked_until IS NULL OR locked_until<=$1) ORDER BY occurred_at,event_id LIMIT $3 FOR UPDATE SKIP LOCKED) RETURNING event_id::text,aggregate_id::text,event_type,payload,occurred_at,attempts`, now, now.Add(lease), limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []event.Outgoing{}
	for rows.Next() {
		var id, aggregate, typ string
		var payload []byte
		var occurred time.Time
		var attempts int
		if err = rows.Scan(&id, &aggregate, &typ, &payload, &occurred, &attempts); err != nil {
			return nil, err
		}
		e, err := event.RehydrateOutgoing(id, aggregate, typ, payload, occurred, attempts)
		if err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	return out, rows.Err()
}
func (r outboxRepo) MarkPublished(ctx context.Context, id string, attempt int, now time.Time) error {
	_, err := r.q.Exec(ctx, `UPDATE outbox_events SET published_at=$3,locked_until=NULL WHERE event_id=$1 AND attempts=$2 AND published_at IS NULL`, id, attempt, now)
	return err
}
func (r outboxRepo) Reschedule(ctx context.Context, id string, attempt int, next time.Time) error {
	_, err := r.q.Exec(ctx, `UPDATE outbox_events SET next_attempt_at=$3,locked_until=NULL WHERE event_id=$1 AND attempts=$2 AND published_at IS NULL`, id, attempt, next)
	return err
}

func (r outboxRepo) OldestPending(ctx context.Context) (*time.Time, error) {
	var oldest *time.Time
	err := r.q.QueryRow(ctx, `SELECT min(occurred_at) FROM outbox_events WHERE published_at IS NULL`).Scan(&oldest)
	return oldest, err
}

func (r inboxRepo) BindTransaction(ctx context.Context, consumer, messageID, transactionID string) error {
	_, err := r.q.Exec(ctx, `UPDATE inbox_messages SET transaction_id=$3::uuid WHERE consumer_name=$1 AND message_id=$2`, consumer, messageID, transactionID)
	return err
}

internal/infra/postgres/ledger_repo.go:
package postgres

import (
	"context"
	"encoding/base64"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/wager"
	"strconv"
	"strings"
	"time"
)

type ledgerRepo struct{ q dbtx }

func (r ledgerRepo) Append(ctx context.Context, e wager.LedgerEntry) error {
	_, err := r.q.Exec(ctx, `SELECT accounting_opening_entry($1::uuid,$2::uuid,$3)`, e.ID(), e.TransactionID(), e.CreatedAt())
	return err
}
func (r ledgerRepo) List(ctx context.Context, w, cursor string, limit int) (port.LedgerPage, error) {
	var seq int64
	out := port.LedgerPage{Entries: []wager.LedgerEntry{}}
	if limit < 1 || limit > 200 {
		return out, apperr.Invalid("limit out of range")
	}
	if cursor != "" {
		b, e := base64.RawURLEncoding.DecodeString(cursor)
		if e != nil {
			return out, apperr.Invalid("invalid cursor")
		}
		parts := strings.Split(string(b), ":")
		if len(parts) != 2 || parts[0] != w {
			return out, apperr.Invalid("invalid cursor")
		}
		seq, e = strconv.ParseInt(parts[1], 10, 64)
		if e != nil || seq < 0 {
			return out, apperr.Invalid("invalid cursor")
		}
	}
	rows, err := r.q.Query(ctx, `SELECT id::text,transaction_id::text,direction,amount_minor,currency,balance_before_minor,balance_after_minor,created_at,seq FROM wallet_ledger_entries WHERE wallet_id=$1 AND seq>$2 ORDER BY seq LIMIT $3`, w, seq, limit+1)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	var last int64
	for rows.Next() {
		var id, tx, cur string
		var dir wager.Direction
		var amount, before, after, s int64
		var at time.Time
		if err = rows.Scan(&id, &tx, &dir, &amount, &cur, &before, &after, &at, &s); err != nil {
			return out, err
		}
		if len(out.Entries) == limit {
			out.NextCursor = base64.RawURLEncoding.EncodeToString([]byte(w + ":" + strconv.FormatInt(last, 10)))
			// Closing can discover a server error after the lookahead row.
			rows.Close()
			return out, rows.Err()
		}
		a, e := money.FromMinor(amount, cur)
		if e != nil {
			return out, e
		}
		b, e := money.FromMinor(before, cur)
		if e != nil {
			return out, e
		}
		c, e := money.FromMinor(after, cur)
		if e != nil {
			return out, e
		}
		entry, e := wager.RehydrateLedgerEntry(id, w, tx, dir, a, b, c, at)
		if e != nil {
			return out, e
		}
		out.Entries = append(out.Entries, entry)
		last = s
	}
	return out, rows.Err()
}
func (r ledgerRepo) Totals(ctx context.Context, w string) (port.LedgerTotals, error) {
	var total string
	var n int64
	var cur string
	err := r.q.QueryRow(ctx, `SELECT w.currency,coalesce(sum(CASE l.direction WHEN 'CREDIT' THEN l.amount_minor::numeric ELSE -l.amount_minor::numeric END),0)::text,count(l.id) FROM wallets w LEFT JOIN wallet_ledger_entries l ON l.wallet_id=w.id WHERE w.id=$1 GROUP BY w.id`, w).Scan(&cur, &total, &n)
	if err != nil {
		return port.LedgerTotals{}, err
	}
	v, err := strconv.ParseInt(total, 10, 64)
	if err != nil {
		return port.LedgerTotals{}, money.ErrOverflow
	}
	m, err := money.FromMinor(v, cur)
	return port.LedgerTotals{Calculated: m, Entries: n}, err
}

internal/infra/postgres/module.go:
package postgres

import (
	"context"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.uber.org/fx"

	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/infra/config"
)

var Module = fx.Module("postgres",
	fx.Provide(
		NewPool,
		fx.Annotate(NewUnitOfWork, fx.As(new(port.UnitOfWork))),
		fx.Annotate(NewReadiness, fx.As(new(port.ReadinessChecker)), fx.ResultTags(`group:"readiness"`)),
	),
)

func NewPool(lc fx.Lifecycle, cfg config.Config) (*pgxpool.Pool, error) {
	pc, err := pgxpool.ParseConfig(cfg.DatabaseURL)
	if err != nil {
		return nil, fmt.Errorf("parse DATABASE_URL: %w", err)
	}
	pc.ConnConfig.RuntimeParams["statement_timeout"] = "10000"
	pc.ConnConfig.RuntimeParams["lock_timeout"] = "8000"
	pool, err := pgxpool.NewWithConfig(context.Background(), pc)
	if err != nil {
		return nil, err
	}
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			err := pool.Ping(ctx)
			if err != nil {
				pool.Close()
			}
			return err
		},
		OnStop: func(context.Context) error { pool.Close(); return nil }, // runs after workers/servers stop
	})
	return pool, nil
}

type pinger interface{ Ping(context.Context) error }

type Readiness struct{ pool pinger }

func NewReadiness(pool *pgxpool.Pool) *Readiness { return &Readiness{pool} }
func (*Readiness) Name() string                  { return "postgres" }
func (r *Readiness) Check(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	return r.pool.Ping(ctx)
}

