package postgres

import (
	"context"
	"errors"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/settlement"
	"github.com/alexandre/wagering/internal/domain/wallet"
	"github.com/jackc/pgx/v5"
	"time"
)

func (t txAdapter) SettlementAudit() port.SettlementAuditStore { return settlementRepo{t.q} }
func (r settlementRepo) readSettlement(ctx context.Context, id string, lock bool) (port.SettlementRecord, error) {
	query := `SELECT id::text,bet_id::text,result_key,distribution_hash,status FROM settlements WHERE id=$1`
	if lock {
		query += ` FOR UPDATE`
	}
	var s port.SettlementRecord
	err := r.q.QueryRow(ctx, query, id).Scan(&s.ID, &s.BetID, &s.ResultID, &s.Hash, &s.Status)
	if errors.Is(err, pgx.ErrNoRows) {
		err = apperr.ErrNotFound
	}
	return s, err
}
func (r settlementRepo) AuditSettlement(ctx context.Context, id string) (port.SettlementAudit, error) {
	out := port.SettlementAudit{Payments: []port.SettlementPayment{}, Postings: []port.SettlementPosting{}}
	s, err := r.readSettlement(ctx, id, false)
	if err != nil {
		return out, err
	}
	out.SettlementRecord = s
	rows, err := r.q.Query(ctx, `SELECT t.id::text,t.wallet_id::text,t.reference_transaction_id::text,t.status,t.amount_minor,t.currency FROM wager_transactions t JOIN settlement_items si ON si.payment_transaction_id=t.id WHERE si.settlement_id=$1 ORDER BY si.ordinal`, id)
	if err != nil {
		return out, err
	}
	for rows.Next() {
		var p port.SettlementPayment
		var n int64
		var cur string
		if err = rows.Scan(&p.ID, &p.WalletID, &p.ReferenceID, &p.Status, &n, &cur); err != nil {
			break
		}
		p.Money, err = money.FromMinor(n, cur)
		if err != nil {
			break
		}
		out.Payments = append(out.Payments, p)
	}
	if err == nil {
		err = rows.Err()
	}
	rows.Close()
	if err != nil {
		return out, err
	}
	rows, err = r.q.Query(ctx, `SELECT e.id::text,e.journal_id::text,e.transaction_id::text,e.account_id::text,e.wallet_id::text,e.account_role,e.direction,e.amount_minor,e.currency,e.balance_before_minor,e.balance_after_minor,e.account_version,e.seq,coalesce(jr.original_journal_id::text,''),e.created_at
 FROM ledger_entries e JOIN wager_transactions t ON t.id=e.transaction_id LEFT JOIN journal_reversals jr ON jr.compensating_journal_id=e.journal_id WHERE t.settlement_id=$1 ORDER BY e.seq`, id)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	for rows.Next() {
		var e port.SettlementPosting
		var n, before, after int64
		var cur string
		if err = rows.Scan(&e.ID, &e.JournalID, &e.TransactionID, &e.AccountID, &e.WalletID, &e.Role, &e.Direction, &n, &cur, &before, &after, &e.Version, &e.Sequence, &e.Reverses, &e.CreatedAt); err != nil {
			return out, err
		}
		e.Money, err = money.FromMinor(n, cur)
		if err != nil {
			return out, err
		}
		e.Before, err = money.FromMinor(before, cur)
		if err != nil {
			return out, err
		}
		e.After, err = money.FromMinor(after, cur)
		if err != nil {
			return out, err
		}
		out.Postings = append(out.Postings, e)
	}
	return out, rows.Err()
}
func (r settlementRepo) LockReversal(ctx context.Context, id string) (port.SettlementRecord, settlement.ReversalFacts, error) {
	f := settlement.ReversalFacts{Accounts: map[string]wallet.Snapshot{}}
	s, err := r.readSettlement(ctx, id, true)
	if err != nil {
		return s, f, err
	}
	f.Status = s.Status
	if s.Status != "PROCESSED" {
		return s, f, nil
	}
	if _, err = r.LockBet(ctx, s.BetID); err != nil {
		return s, f, err
	}
	if _, err = r.q.Exec(ctx, `SELECT id FROM bet_commitments WHERE bet_id=$1 ORDER BY id FOR UPDATE`, s.BetID); err != nil {
		return s, f, err
	}
	if _, err = r.q.Exec(ctx, `SELECT a.id FROM ledger_accounts a WHERE a.wallet_id IN (SELECT wallet_id FROM bet_commitments WHERE bet_id=$1) ORDER BY a.id FOR NO KEY UPDATE`, s.BetID); err != nil {
		return s, f, err
	}
	rows, err := r.q.Query(ctx, `SELECT a.id::text,w.player_id::text,a.currency,a.balance_minor,a.version,a.created_at,a.updated_at FROM ledger_accounts a JOIN wallets w ON w.id=a.wallet_id WHERE a.wallet_id IN (SELECT wallet_id FROM bet_commitments WHERE bet_id=$1) ORDER BY a.id`, s.BetID)
	if err != nil {
		return s, f, err
	}
	for rows.Next() {
		a, e := scanWallet(rows)
		if e != nil {
			err = e
			break
		}
		f.Accounts[a.ID()] = a.Snapshot()
	}
	if err == nil {
		err = rows.Err()
	}
	rows.Close()
	if err != nil {
		return s, f, err
	}
	rows, err = r.q.Query(ctx, `SELECT `+txCols+` FROM wager_transactions WHERE id IN (SELECT payment_transaction_id FROM settlement_items WHERE settlement_id=$1 AND kind='RETURN') ORDER BY id`, s.ID)
	if err != nil {
		return s, f, err
	}
	for rows.Next() {
		p, e := scanTx(rows)
		if e != nil {
			err = e
			break
		}
		f.Payments = append(f.Payments, p.Snapshot())
	}
	if err == nil {
		err = rows.Err()
	}
	rows.Close()
	if err != nil {
		return s, f, err
	}
	rows, err = r.q.Query(ctx, `SELECT d.account_id::text,c.account_id::text,j.amount_minor,j.currency FROM ledger_journals j JOIN settlement_items si ON si.id=j.settlement_item_id JOIN ledger_entries d ON d.journal_id=j.id AND d.direction='DEBIT' JOIN ledger_entries c ON c.journal_id=j.id AND c.direction='CREDIT' WHERE si.settlement_id=$1 ORDER BY greatest(d.seq,c.seq) DESC`, id)
	if err != nil {
		return s, f, err
	}
	defer rows.Close()
	for rows.Next() {
		var j settlement.ReversalJournal
		var n int64
		var cur string
		if err = rows.Scan(&j.DebitAccountID, &j.CreditAccountID, &n, &cur); err != nil {
			return s, f, err
		}
		j.Amount, err = money.FromMinor(n, cur)
		if err != nil {
			return s, f, err
		}
		f.Journals = append(f.Journals, j)
	}
	return s, f, rows.Err()
}
func (r settlementRepo) ReverseSettlement(ctx context.Context, id string, now time.Time) error {
	_, err := r.q.Exec(ctx, `SELECT accounting_reverse_settlement($1,$2)`, id, now)
	return err
}

package postgres

import (
	"context"
	"errors"
	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/settlement"
	"github.com/alexandre/wagering/internal/domain/wager"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"time"
)

type settlementRepo struct{ q dbtx }

func (t txAdapter) Settlements() port.SettlementStore { return settlementRepo{t.q} }
func (r settlementRepo) CreateBet(ctx context.Context, b settlement.Bet) error {
	_, err := r.q.Exec(ctx, `INSERT INTO bets(id,provider_id,round_id,game_id,currency,created_at) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(id) DO NOTHING`, b.ID, b.ProviderID, b.RoundID, b.GameID, b.Currency, b.CreatedAt)
	if err != nil {
		return err
	}
	old, err := r.LockBet(ctx, b.ID)
	if err != nil {
		return err
	}
	if old.ProviderID != b.ProviderID || old.RoundID != b.RoundID || old.GameID != b.GameID || old.Currency != b.Currency {
		return apperr.ErrIdempotencyConflict
	}
	return nil
}
func (r settlementRepo) LockBet(ctx context.Context, id string) (settlement.Bet, error) {
	var b settlement.Bet
	err := r.q.QueryRow(ctx, `SELECT id::text,provider_id,round_id,game_id,currency,status,created_at FROM bets WHERE id=$1 FOR UPDATE`, id).Scan(&b.ID, &b.ProviderID, &b.RoundID, &b.GameID, &b.Currency, &b.Status, &b.CreatedAt)
	if errors.Is(err, pgx.ErrNoRows) {
		err = apperr.ErrNotFound
	}
	return b, err
}
func (r settlementRepo) Commitments(ctx context.Context, id string) ([]settlement.Commitment, error) {
	rows, err := r.q.Query(ctx, `SELECT c.id::text,t.id::text,t.external_transaction_id,c.wallet_id::text,t.player_id::text,t.game_id,c.remaining_minor,c.currency FROM bet_commitments c JOIN wager_transactions t ON t.id=c.bet_transaction_id WHERE c.bet_id=$1 ORDER BY c.id FOR UPDATE OF c`, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []settlement.Commitment
	for rows.Next() {
		var c settlement.Commitment
		var amount int64
		var currency string
		if err := rows.Scan(&c.ID, &c.TransactionID, &c.ExternalID, &c.WalletID, &c.PlayerID, &c.GameID, &amount, &currency); err != nil {
			return nil, err
		}
		c.Remaining, err = money.FromMinor(amount, currency)
		if err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}
func (r settlementRepo) FindSettlement(ctx context.Context, bet string) (port.SettlementRecord, error) {
	var s port.SettlementRecord
	err := r.q.QueryRow(ctx, `SELECT id::text,bet_id::text,result_key,distribution_hash,status FROM settlements WHERE bet_id=$1`, bet).Scan(&s.ID, &s.BetID, &s.ResultID, &s.Hash, &s.Status)
	if errors.Is(err, pgx.ErrNoRows) {
		err = apperr.ErrNotFound
	}
	return s, err
}
func (r settlementRepo) BindBet(ctx context.Context, tid, bid string) error {
	tag, err := r.q.Exec(ctx, `UPDATE wager_transactions SET bet_id=$2 WHERE id=$1 AND status='PENDING' AND bet_id IS NULL`, tid, bid)
	if err == nil && tag.RowsAffected() != 1 {
		return apperr.ErrConcurrentModification
	}
	return err
}
func (r settlementRepo) SaveSettlement(ctx context.Context, s port.SettlementRecord, b settlement.Bet, d settlement.Distribution, cs []settlement.Commitment, at time.Time) error {
	_, err := r.q.Exec(ctx, `INSERT INTO settlements(id,bet_id,currency,result_key,distribution_hash,created_at) VALUES($1,$2,$3,$4,$5,$6)`, s.ID, b.ID, b.Currency, s.ResultID, s.Hash, at)
	if err != nil {
		return err
	}
	byExternal := map[string]settlement.Commitment{}
	for _, c := range cs {
		byExternal[c.ExternalID] = c
	}
	ordinal := 0
	for _, a := range d.Allocations {
		_, err = r.q.Exec(ctx, `INSERT INTO settlement_items(settlement_id,bet_id,currency,kind,source_commitment_id,target_commitment_id,amount_minor,ordinal) VALUES($1,$2,$3,'ALLOCATION',$4,$5,$6,$7)`, s.ID, b.ID, b.Currency, byExternal[a.From].ID, byExternal[a.To].ID, a.Money.Minor(), ordinal)
		if err != nil {
			return err
		}
		ordinal++
	}
	for _, ret := range d.Returns {
		c := byExternal[ret.ExternalID]
		tid := uuid.NewString()
		external := "settlement:" + s.ID + ":" + c.ID
		hash := wager.PayloadHash(wager.HashInput{ProviderID: b.ProviderID, ExternalTransactionID: external, PlayerID: c.PlayerID, WalletID: c.WalletID, RoundID: b.RoundID, GameID: c.GameID, Kind: "WIN", Amount: ret.Money.Amount(), Currency: b.Currency, ReferenceExternalTransactionID: c.ExternalID})
		payment, e := wager.NewExternal(wager.ExternalParams{ID: tid, ProviderID: b.ProviderID, ExternalID: external, IdempotencyKey: external, PayloadHash: hash, WalletID: c.WalletID, PlayerID: c.PlayerID, RoundID: b.RoundID, GameID: c.GameID, Kind: wager.KindWin, Amount: ret.Money, ReferenceExternalID: c.ExternalID, CorrelationID: s.ID}, at)
		if e != nil {
			return e
		}
		if e = payment.ResolveReference(c.TransactionID); e != nil {
			return e
		}
		if e = (transactionRepo{r.q}).Insert(ctx, payment); e != nil {
			return e
		}
		if _, e = r.q.Exec(ctx, `UPDATE wager_transactions SET bet_id=$2,settlement_id=$3 WHERE id=$1`, tid, b.ID, s.ID); e != nil {
			return e
		}
		if _, e = r.q.Exec(ctx, `INSERT INTO settlement_items(settlement_id,bet_id,currency,kind,source_commitment_id,amount_minor,ordinal,payment_transaction_id) VALUES($1,$2,$3,'RETURN',$4,$5,$6,$7)`, s.ID, b.ID, b.Currency, c.ID, ret.Money.Minor(), ordinal, tid); e != nil {
			return e
		}
		ordinal++
	}
	_, err = r.q.Exec(ctx, `UPDATE bets SET status='CLOSED',closed_at=$2,version=version+1 WHERE id=$1`, b.ID, at)
	return err
}

func (t txAdapter) SettleDelivery(ctx context.Context, messageID, hash, id string, now time.Time) error {
	const consumer = "settlements"
	inbox := inboxRepo{t.q}
	state, err := inbox.Begin(ctx, consumer, messageID, hash, now)
	if err != nil {
		return err
	}
	if state == port.InboxConflict {
		return apperr.ErrMessageConflict
	}
	if state == port.InboxCompleted {
		return nil
	}
	if _, err = t.q.Exec(ctx, `SELECT accounting_execute_settlement($1,$2)`, id, now); err != nil {
		return err
	}
	if _, err = t.q.Exec(ctx, `UPDATE inbox_messages SET settlement_id=$3 WHERE consumer_name=$1 AND message_id=$2`, consumer, messageID, id); err != nil {
		return err
	}
	_, err = t.q.Exec(ctx, `UPDATE inbox_messages SET completed_at=$3 WHERE consumer_name=$1 AND message_id=$2`, consumer, messageID, now)
	return err
}

