)

type transactionRepo struct{ q dbtx }

const txCols = `id::text,origin,coalesce(provider_id,''),coalesce(external_transaction_id,''),coalesce(idempotency_key,''),coalesce(payload_hash,''),wallet_id::text,player_id::text,coalesce(round_id,''),coalesce(game_id,''),kind,amount_minor,currency,coalesce(reference_external_id,''),coalesce(reference_transaction_id::text,''),status,coalesce(failure_code,''),balance_after_minor,attempts,next_attempt_at,expires_at,created_at,updated_at,correlation_id,causation_id`

func scanTx(row pgx.Row) (*wager.Transaction, error) {
	var s wager.Snapshot
	var amount int64
	var currency string
	var balance *int64
	if err := row.Scan(&s.ID, &s.Origin, &s.ProviderID, &s.ExternalID, &s.IdempotencyKey, &s.PayloadHash, &s.WalletID, &s.PlayerID, &s.RoundID, &s.GameID, &s.Kind, &amount, &currency, &s.ReferenceExternalID, &s.ReferenceID, &s.Status, &s.FailureCode, &balance, &s.Attempts, &s.NextAttemptAt, &s.ExpiresAt, &s.CreatedAt, &s.UpdatedAt, &s.CorrelationID, &s.CausationID); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, apperr.ErrNotFound
		}
		return nil, err
	}
	var err error
	s.Amount, err = money.FromMinor(amount, currency)
	if err != nil {
		return nil, err
	}
	if balance != nil {
		b, e := money.FromMinor(*balance, currency)
		if e != nil {
			return nil, e
		}
		s.BalanceAfter = &b
	}
	return wager.Rehydrate(s)
}
func (r transactionRepo) insert(ctx context.Context, t *wager.Transaction, conflict bool) (bool, error) {
	s := t.Snapshot()
	var balance *int64
	if s.BalanceAfter != nil {
		b := s.BalanceAfter.Minor()
		balance = &b
	}
	sql := `INSERT INTO wager_transactions(id,origin,provider_id,external_transaction_id,idempotency_key,payload_hash,wallet_id,player_id,round_id,game_id,kind,amount_minor,currency,reference_external_id,reference_transaction_id,status,failure_code,balance_after_minor,attempts,next_attempt_at,expires_at,created_at,updated_at,correlation_id,causation_id,result_account_id) VALUES($1,$2,nullif($3,''),nullif($4,''),nullif($5,''),nullif($6,''),$7,$8,nullif($9,''),nullif($10,''),$11,$12,$13,nullif($14,''),nullif($15,'')::uuid,$16,nullif($17,''),$18,$19,$20,$21,$22,$23,$24,$25,CASE WHEN $16='PROCESSED' THEN (SELECT id FROM ledger_accounts WHERE wallet_id=$7::uuid AND role='GUARANTEE') END)`
	if conflict {
		sql += ` ON CONFLICT DO NOTHING`
	}
	tag, err := r.q.Exec(ctx, sql, s.ID, s.Origin, s.ProviderID, s.ExternalID, s.IdempotencyKey, s.PayloadHash, s.WalletID, s.PlayerID, s.RoundID, s.GameID, s.Kind, s.Amount.Minor(), s.Amount.Currency(), s.ReferenceExternalID, s.ReferenceID, s.Status, s.FailureCode, balance, s.Attempts, s.NextAttemptAt, s.ExpiresAt, s.CreatedAt, s.UpdatedAt, s.CorrelationID, s.CausationID)
	return tag.RowsAffected() == 1, err
}
func (r transactionRepo) Insert(ctx context.Context, t *wager.Transaction) error {
	_, err := r.insert(ctx, t, false)
	return err
}
func (r transactionRepo) InsertPending(ctx context.Context, t *wager.Transaction) (bool, error) {
	return r.insert(ctx, t, true)
}
func (r transactionRepo) FindByID(ctx context.Context, id string) (*wager.Transaction, error) {
	return scanTx(r.q.QueryRow(ctx, `SELECT `+txCols+` FROM wager_transactions WHERE id=$1::uuid`, id))
}
func (r transactionRepo) FindByIdempotencyKey(ctx context.Context, p, k string) (*wager.Transaction, error) {
	return scanTx(r.q.QueryRow(ctx, `SELECT `+txCols+` FROM wager_transactions WHERE origin='EXTERNAL' AND provider_id=$1 AND idempotency_key=$2`, p, k))
}
func (r transactionRepo) FindByExternalID(ctx context.Context, p, k string) (*wager.Transaction, error) {
	return scanTx(r.q.QueryRow(ctx, `SELECT `+txCols+` FROM wager_transactions WHERE origin='EXTERNAL' AND provider_id=$1 AND external_transaction_id=$2`, p, k))
}
func (r transactionRepo) Update(ctx context.Context, t *wager.Transaction) error {
	s := t.Snapshot()
	var b *int64
	if s.BalanceAfter != nil {
		v := s.BalanceAfter.Minor()
		b = &v
	}
	tag, err := r.q.Exec(ctx, `UPDATE wager_transactions SET reference_transaction_id=nullif($2,'')::uuid,status=$3,failure_code=nullif($4,''),balance_after_minor=$5,attempts=$6,next_attempt_at=$7,expires_at=$8,updated_at=$9,result_account_id=CASE WHEN $3='PROCESSED' THEN (SELECT id FROM ledger_accounts WHERE wallet_id=wager_transactions.wallet_id AND role='GUARANTEE') END WHERE id=$1 AND status IN ('PENDING','PENDING_REFERENCE')`, s.ID, s.ReferenceID, s.Status, s.FailureCode, b, s.Attempts, s.NextAttemptAt, s.ExpiresAt, s.UpdatedAt)
	if err == nil && tag.RowsAffected() != 1 {
		return apperr.ErrConcurrentModification
	}
	return err
}
func (r transactionRepo) ClaimDue(ctx context.Context, now time.Time, limit int) ([]*wager.Transaction, error) {
	rows, err := r.q.Query(ctx, `SELECT `+txCols+` FROM wager_transactions WHERE status IN ('PENDING','PENDING_REFERENCE') AND settlement_id IS NULL AND coalesce(next_attempt_at,created_at)<=$1 ORDER BY coalesce(next_attempt_at,created_at),id LIMIT $2 FOR UPDATE SKIP LOCKED`, now, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []*wager.Transaction{}
	for rows.Next() {
		t, e := scanTx(rows)
		if e != nil {
			return nil, e
		}
		out = append(out, t)
	}
	return out, rows.Err()
}
func (r transactionRepo) HasReversal(ctx context.Context, id string) (bool, error) {
	var yes bool
	err := r.q.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM wager_transactions WHERE reference_transaction_id=$1 AND kind IN ('REFUND','ROLLBACK') AND status='PROCESSED')`, id).Scan(&yes)
	return yes, err
}

internal/infra/postgres/uow.go:
package postgres

import (
	"context"
	"errors"
	"io"
	"net"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
)

// dbtx is satisfied by pgx.Tx and *pgxpool.Pool.
type dbtx interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

type transactionBeginner interface {
	BeginTx(context.Context, pgx.TxOptions) (pgx.Tx, error)
}

type UnitOfWork struct{ pool transactionBeginner }

func NewUnitOfWork(pool *pgxpool.Pool) *UnitOfWork { return &UnitOfWork{pool} }

func (u *UnitOfWork) Do(ctx context.Context, fn func(context.Context, port.Tx) error) error {
	return u.run(ctx, pgx.TxOptions{IsoLevel: pgx.ReadCommitted}, fn)
}

func (u *UnitOfWork) DoSnapshot(ctx context.Context, fn func(context.Context, port.Tx) error) error {
	return u.run(ctx, pgx.TxOptions{IsoLevel: pgx.RepeatableRead, AccessMode: pgx.ReadOnly}, fn)
}

func (u *UnitOfWork) run(ctx context.Context, opts pgx.TxOptions, fn func(context.Context, port.Tx) error) error {
	t, err := u.pool.BeginTx(ctx, opts)
	if err != nil {
		return apperr.Transient(err)
	}
	defer func() {
		c, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		_ = t.Rollback(c)
	}() // no-op after a successful commit
	if err := fn(ctx, txAdapter{t}); err != nil {
		return classify(err)
	}
	if err := t.Commit(ctx); err != nil {
		return classify(err)
	}
	return nil
}

// classify marks retryable SQLSTATEs (serialization_failure 40001, deadlock 40P01, connection class 08) as transient.
func classify(err error) error {
	var ne net.Error
	if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) || errors.As(err, &ne) || errors.Is(err, context.DeadlineExceeded) || errors.Is(err, apperr.ErrConcurrentModification) {
		return apperr.Transient(err)
	}
	var pe *pgconn.PgError
	if errAs(err, &pe) {
		if pe.Code == "23514" || pe.Code == "23503" || pe.Code == "P0001" || pe.Code == "42601" {
			return apperr.Permanent(err)
		}
		if pe.Code == "22P02" {
			return apperr.Invalid("invalid identifier")
		}
		if pe.Code == "55P03" || pe.Code == "40001" || pe.Code == "40P01" {
			return apperr.Transient(errors.Join(apperr.ErrConcurrentModification, err))
		}
		if pe.Code == "57P01" || pe.Code == "53300" || pe.Code == "57014" || (len(pe.Code) >= 2 && pe.Code[:2] == "08") {
			return apperr.Transient(err)
		}
	}
	return err
}

type txAdapter struct{ q dbtx }

func (t txAdapter) Wallets() port.WalletRepository           { return walletRepo{t.q} }
func (t txAdapter) Transactions() port.TransactionRepository { return transactionRepo{t.q} }
func (t txAdapter) Ledger() port.LedgerRepository            { return ledgerRepo{t.q} }
func (t txAdapter) Inbox() port.InboxRepository              { return inboxRepo{t.q} }
func (t txAdapter) Outbox() port.OutboxRepository            { return outboxRepo{t.q} }

func (t txAdapter) SettleByID(ctx context.Context, id string) error {
	_, err := t.q.Exec(ctx, `SELECT accounting_execute_settlement($1::uuid,clock_timestamp())`, id)
	return classify(err)
}

internal/infra/postgres/wallet_repo.go:
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/domain/money"
	"github.com/alexandre/wagering/internal/domain/wallet"
)

var _ port.WalletRepository = walletRepo{}

type walletRepo struct{ q dbtx }

const walletCols = `id::text, player_id::text, currency, balance_minor, version, created_at, updated_at`

func (r walletRepo) Create(ctx context.Context, w *wallet.Wallet) error {
	s := w.Snapshot()
	_, err := r.q.Exec(ctx, `WITH created AS (
        INSERT INTO wallets(id,player_id,currency,created_at,updated_at) VALUES($1::uuid,$2::uuid,$3,$6,$7) RETURNING id,currency
    ) INSERT INTO ledger_accounts(wallet_id,currency,role,balance_minor,version,created_at,updated_at)
      SELECT id,currency,role,CASE role WHEN 'GUARANTEE' THEN $4::bigint ELSE 0 END,$5,$6,$7
      FROM created CROSS JOIN (VALUES ('GUARANTEE'),('OPERATIONAL')) roles(role)`,
		s.ID, s.PlayerID, s.Balance.Currency(), s.Balance.Minor(), s.Version, s.CreatedAt, s.UpdatedAt)
	var pe *pgconn.PgError
	if errors.As(err, &pe) && pe.Code == "23505" {
		return apperr.ErrWalletExists
	}
	return err
}

func (r walletRepo) Get(ctx context.Context, id string) (*wallet.Wallet, error) {
	return scanWallet(r.q.QueryRow(ctx, `SELECT `+walletCols+` FROM wallet_balances WHERE id = $1::uuid`, id))
}

// GetForUpdate takes a row lock on THIS wallet only; independent wallets proceed in parallel.
func (r walletRepo) GetForUpdate(ctx context.Context, id string) (*wallet.Wallet, error) {
	return scanWallet(r.q.QueryRow(ctx, `SELECT `+walletCols+` FROM wallet_balances WHERE id = $1::uuid FOR NO KEY UPDATE`, id))
}

// Save is a compare-and-swap on version (defense in depth on top of the row lock).
func (r walletRepo) Save(ctx context.Context, w *wallet.Wallet, expectedVersion int64) error {
	s := w.Snapshot()
	tag, err := r.q.Exec(ctx, `UPDATE ledger_accounts SET balance_minor = $2, version = $3, updated_at = $4
		WHERE wallet_id = $1::uuid AND role='GUARANTEE' AND version = $5`, s.ID, s.Balance.Minor(), s.Version, s.UpdatedAt, expectedVersion)
	if err != nil {
		return err
	}
	if tag.RowsAffected() != 1 {
		return apperr.ErrConcurrentModification
	}
	return nil
}

func scanWallet(row pgx.Row) (*wallet.Wallet, error) {
	var (
		id, player, cur string
		minor, ver      int64
		created, upd    time.Time
	)
	if err := row.Scan(&id, &player, &cur, &minor, &ver, &created, &upd); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, apperr.ErrWalletNotFound
		}
		return nil, err
	}
	bal, err := money.FromMinor(minor, cur)
	if err != nil {
		return nil, err
	}
	return wallet.Rehydrate(wallet.Snapshot{ID: id, PlayerID: player, Balance: bal, Version: ver, CreatedAt: created, UpdatedAt: upd})
}

