internal/platform/worker/worker.go:
// Package worker owns component goroutines and drains them under one shutdown budget.
package worker

import (
	"context"
	"errors"
	"fmt"
	"github.com/alexandre/wagering/internal/infra/config"
	"go.uber.org/fx"
	"log/slog"
	"sync"
	"time"
)

type task struct {
	name string
	run  func(context.Context) error
}
type Group struct {
	tasks    []task
	drains   []func(context.Context) error
	cancel   context.CancelFunc
	done     chan struct{}
	mu       sync.Mutex
	failure  error
	log      *slog.Logger
	shutdown fx.Shutdowner
	budget   time.Duration
}

func NewGroup(log *slog.Logger, shutdown fx.Shutdowner, cfg config.Config) *Group {
	return &Group{log: log, shutdown: shutdown, budget: cfg.ShutdownTimeout, done: make(chan struct{})}
}
func Register(g *Group, name string, log *slog.Logger, run func(context.Context) error) {
	g.tasks = append(g.tasks, task{name, run})
}

// Drain registers a component's stop-admission-and-drain function, before Install.
func (g *Group) Drain(f func(context.Context) error) { g.drains = append(g.drains, f) }

// Install is invoked LAST in the Fx graph: shutdown completes before dependency hooks.
func (g *Group) Install(lc fx.Lifecycle) {
	lc.Append(fx.Hook{OnStart: func(context.Context) error {
		ctx, cancel := context.WithCancel(context.Background())
		g.cancel = cancel
		var wg sync.WaitGroup
		for _, t := range g.tasks {
			wg.Add(1)
			go func(t task) {
				defer wg.Done()
				g.log.Info("worker started", "worker", t.name)
				err := t.run(ctx)
				if ctx.Err() == nil {
					if err == nil {
						err = errors.New("unexpected component termination")
					}
					g.mu.Lock()
					g.failure = errors.Join(g.failure, fmt.Errorf("%s: %w", t.name, err))
					g.mu.Unlock()
					g.log.Error("component failed", "worker", t.name, "err", err)
					cancel()
					_ = g.shutdown.Shutdown(fx.ExitCode(1))
				}
				g.log.Info("worker stopped", "worker", t.name)
			}(t)
		}
		go func() { wg.Wait(); close(g.done) }()
		return nil
	}, OnStop: func(parent context.Context) error {
		// Stop all polls together, before waiting on any worker or HTTP handler.
		g.cancel()
		ctx, cancel := context.WithTimeout(parent, g.budget)
		defer cancel()
		results := make(chan error, len(g.drains))
		for _, drain := range g.drains {
			go func(f func(context.Context) error) { results <- f(ctx) }(drain)
		}
		var errs []error
		for range g.drains {
			select {
			case err := <-results:
				errs = append(errs, err)
			case <-ctx.Done():
				return errors.Join(append(errs, ctx.Err())...)
			}
		}
		select {
		case <-g.done:
		case <-ctx.Done():
			return errors.Join(append(errs, ctx.Err())...)
		}
		g.mu.Lock()
		defer g.mu.Unlock()
		return errors.Join(append(errs, g.failure)...)
	}})
}
func Every(interval time.Duration, step func(context.Context) error, onErr func(error)) func(context.Context) error {
	return func(ctx context.Context) error {
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return nil
			case <-ticker.C:
				if ctx.Err() != nil {
					return nil
				}
				// Each step is bounded even when a dependency stops responding.
				call, cancel := context.WithTimeout(ctx, 15*time.Second)
				err := step(call)
				cancel()
				if err != nil && onErr != nil {
					onErr(err)
				}
			}
		}
	}
}

internal/testsupport/settlementfacts/com:
package settlementfacts

import "fmt"

// Commitment is a test projection of durable bet funding, not a production
// entity. Remaining is money still available to this bet; Settlement identifies
// the durable consumption. Neither aggregate wallet cash nor another bet can
// substitute for this record.
type Commitment struct {
	ExternalID, Bet, Wallet, Guarantee, Provider, Currency, Settlement string
	Stake, Remaining                                                   int64
}

// CompareCommitments matches literal expected records without deriving funding
// from balances or recomputing a distribution. Order is immaterial; identity and
// multiplicity are not. It also rejects duplicate records in expected fixtures.
func CompareCommitments(got, want []Commitment) error {
	if len(got) != len(want) {
		return fmt.Errorf("commitment count: got=%d want=%d", len(got), len(want))
	}
	expected := map[string]Commitment{}
	key := func(c Commitment) string { return c.Provider + "\x00" + c.ExternalID }
	for _, c := range want {
		k := key(c)
		if c.ExternalID == "" || c.Provider == "" {
			return fmt.Errorf("expected commitment lacks identity")
		}
		if _, ok := expected[k]; ok {
			return fmt.Errorf("duplicate expected commitment: %s", c.ExternalID)
		}
		expected[k] = c
	}
	for _, c := range got {
		k := key(c)
		w, ok := expected[k]
		if !ok || c != w {
			return fmt.Errorf("unexpected or changed commitment: got=%+v want=%+v", c, w)
		}
		delete(expected, k)
	}
	return nil
}

internal/testsupport/settlementfacts/fac:
// Package settlementfacts contains assertions shared only by tests.
package settlementfacts

import (
	"fmt"
	"reflect"
	"slices"
	"strings"
)

// Test-side projections, not production DTO/schema requirements. A SQL or API
// adapter must supply observed facts; this comparator never executes settlement.
// One account may have several postings with distinct intermediate balances.
type Posting struct {
	Account, Direction, Currency string
	Amount, Before, After        int64
}
type Journal struct {
	ID, Bet, Reverses string
	Postings          []Posting
}
type Facts struct {
	Balances map[string]int64
	Journals []Journal
}

// Compare literal expected journals as a multiset. Ordering a debit and its
// credit in SQL is not a business rule. Grouping them in the SAME journal is.
// IDs of newly generated journals are opaque, but must be unique and nonempty.
func Compare(got, want Facts) error {
	if !reflect.DeepEqual(got.Balances, want.Balances) {
		return fmt.Errorf("account snapshots differ: got=%v want=%v", got.Balances, want.Balances)
	}
	if len(got.Journals) != len(want.Journals) {
		return fmt.Errorf("journal count: got=%d want=%d", len(got.Journals), len(want.Journals))
	}
	canonical := func(j Journal) string {
		postings := append([]Posting(nil), j.Postings...)
		slices.SortFunc(postings, func(a, b Posting) int { return strings.Compare(fmt.Sprint(a), fmt.Sprint(b)) })
		return fmt.Sprintf("%q/%q/%v", j.Bet, j.Reverses, postings)
	}
	expected := map[string]int{}
	for _, j := range want.Journals {
		expected[canonical(j)]++
	}
	seen := map[string]bool{}
	for _, j := range got.Journals {
		if j.ID == "" || seen[j.ID] {
			return fmt.Errorf("missing/duplicate journal ID: %q", j.ID)
		}
		seen[j.ID] = true
		key := canonical(j)
		if expected[key] == 0 {
			return fmt.Errorf("unexpected journal or counterpart: %+v", j)
		}
		expected[key]--
	}
	return nil
}

internal/testsupport/settlementfacts/obs:
package settlementfacts

import (
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"time"
)

// LedgerObservation is a test-side wire contract, deliberately independent of
// the existing production DTO. Each entry must identify its own account.
type LedgerObservation struct {
	ID            string       `json:"id"`
	WalletID      string       `json:"walletId"`
	TransactionID string       `json:"transactionId"`
	Direction     string       `json:"direction"`
	Money         DecimalMoney `json:"money"`
	BalanceBefore DecimalMoney `json:"balanceBefore"`
	BalanceAfter  DecimalMoney `json:"balanceAfter"`
	CreatedAt     time.Time    `json:"createdAt"`
}
type DecimalMoney struct {
	Amount   string `json:"amount"`
	Currency string `json:"currency"`
}

// CompareLedger requires the complete ordered projection; a correct set of IDs
// is insufficient. Expected rows come from a separate SQL read plus literal
// financial checks, not from decoding the same HTTP response twice.
func CompareLedger(got, want []LedgerObservation) error {
	if len(got) != len(want) {
		return fmt.Errorf("ledger size: got %d want %d", len(got), len(want))
	}
	seen := map[string]bool{}
	for i, g := range got {
		w := want[i]
		if g.ID == "" || g.WalletID == "" || g.TransactionID == "" || seen[g.ID] {
			return fmt.Errorf("invalid ledger identity at %d", i)
		}
		seen[g.ID] = true
		_, offset := g.CreatedAt.Zone()
		if g.CreatedAt.IsZero() || offset != 0 || !g.CreatedAt.Equal(w.CreatedAt) {
			return fmt.Errorf("ledger time at %d", i)
		}
		g.CreatedAt, w.CreatedAt = time.Time{}, time.Time{}
		if !reflect.DeepEqual(g, w) {
			return fmt.Errorf("ledger content/order at %d: got %+v want %+v", i, g, w)
		}
	}
	return nil
}

type TerminalObservation struct {
	ID, Aggregate, Kind string
	OccurredAt          time.Time
	Payload             []byte
}
type TimeWindow struct{ Earliest, Latest time.Time }

// CheckSettlementRequest validates the durable command envelope. Completion
// is represented separately by the funded WIN transactions and their events.
func CheckSettlementRequest(rows []TerminalObservation, settlement string, window TimeWindow) error {
	if settlement == "" || window.Earliest.IsZero() || window.Latest.Before(window.Earliest) || len(rows) != 1 {
		return fmt.Errorf("invalid request fixture or count")
	}
	r := rows[0]
	var e struct {
		EventID, AggregateID, EventType, CorrelationID string
		Version                                        int
		OccurredAt                                     time.Time
		Data                                           map[string]json.RawMessage
	}
	if err := json.Unmarshal(r.Payload, &e); err != nil {
		return err
	}
	if r.ID == "" || r.Aggregate != settlement || e.AggregateID != settlement || e.EventID != r.ID || e.EventType != r.Kind || r.Kind != "SettlementRequested" || e.CorrelationID != settlement || e.Version != 1 {
		return fmt.Errorf("invalid request identity")
	}
	_, offset := e.OccurredAt.Zone()
	if e.OccurredAt.IsZero() || offset != 0 || !e.OccurredAt.Equal(r.OccurredAt) || e.OccurredAt.Before(window.Earliest) || e.OccurredAt.After(window.Latest) {
		return fmt.Errorf("invalid request time")
	}
	var sid string
	if err := json.Unmarshal(e.Data["settlementId"], &sid); err != nil || sid != settlement || len(e.Data) != 1 {
		return fmt.Errorf("request must carry only settlement identity")
	}
	return nil
}

// TransferIntent states exact declared counterparties and amount. Intermediate
// balances are checked in ordered account histories, allowing independent equal
// transfers to run in either order. This does not calculate a distribution.
type TransferIntent struct {
	Bet, From, To, Currency string
	Amount                  int64
}

func CompareTransfers(journals []Journal, want []TransferIntent) error {
	expected := map[TransferIntent]int{}
	seen := map[string]bool{}
	for _, w := range want {
		if w.Bet == "" || w.From == w.To || w.Amount <= 0 {
			return fmt.Errorf("invalid transfer fixture")
		}
		expected[w]++
	}
	if len(journals) != len(want) {
		return fmt.Errorf("transfer count")
	}
	for _, j := range journals {
		if j.ID == "" || seen[j.ID] || j.Reverses != "" || len(j.Postings) != 2 {
			return fmt.Errorf("invalid transfer journal")
		}
		seen[j.ID] = true
		debit, credit := j.Postings[0], j.Postings[1]
		if debit.Direction == "CREDIT" {
			debit, credit = credit, debit
		}
		if debit.Direction != "DEBIT" || credit.Direction != "CREDIT" {
			return fmt.Errorf("invalid transfer directions")
		}

		if debit.Amount != credit.Amount || debit.Currency != credit.Currency {
			return fmt.Errorf("unbalanced transfer")
		}
		key := TransferIntent{j.Bet, debit.Account, credit.Account, debit.Currency, debit.Amount}
		if expected[key] == 0 {
			return fmt.Errorf("unexpected transfer %+v", key)
		}
		// The matching intent guarantees a positive amount. Check arithmetic
		// preconditions before computing the exact resulting balances.
		if debit.Before < debit.Amount || credit.Before < 0 || credit.Before > math.MaxInt64-credit.Amount {
			return fmt.Errorf("invalid posting balance")
		}
		if debit.After != debit.Before-debit.Amount || credit.After != credit.Before+credit.Amount {
			return fmt.Errorf("invalid posting movement")
		}
		expected[key]--
	}
	return nil
}

// BalanceExpectation identifies a specific persisted account movement. Version
// is exact; accepting any positive version loses the ordering guarantee.
type BalanceExpectation struct {
	WalletID      string       `json:"walletId"`
	TransactionID string       `json:"transactionId"`
	Direction     string       `json:"direction"`
	Money         DecimalMoney `json:"money"`
	BalanceBefore DecimalMoney `json:"balanceBefore"`
	BalanceAfter  DecimalMoney `json:"balanceAfter"`
	WalletVersion int64        `json:"walletVersion"`
}

func CheckBalanceEvents(rows []TerminalObservation, want []BalanceExpectation, correlation string, window TimeWindow) error {
	expected := map[string]BalanceExpectation{}
	key := func(v BalanceExpectation) string { return v.WalletID + "\x00" + v.TransactionID }
	for _, w := range want {
		if w.WalletID == "" || w.TransactionID == "" || w.WalletVersion < 1 {
			return fmt.Errorf("invalid balance fixture")
		}
		if _, ok := expected[key(w)]; ok {
			return fmt.Errorf("duplicate balance fixture")
		}
		expected[key(w)] = w
	}
	if len(rows) != len(want) {
		return fmt.Errorf("balance event count")
	}
	seen := map[string]bool{}
	for _, r := range rows {
		var e struct {
			EventID, AggregateID, EventType, CorrelationID string
			Version                                        int
			OccurredAt                                     time.Time
			Data                                           BalanceExpectation
		}
		if err := json.Unmarshal(r.Payload, &e); err != nil {
			return err
		}
		if r.ID == "" || seen[r.ID] || e.EventID != r.ID || r.Kind != "WalletBalanceChanged" || e.EventType != r.Kind || r.Aggregate != e.Data.WalletID || e.AggregateID != e.Data.WalletID || e.CorrelationID != correlation || e.Version != 1 {
			return fmt.Errorf("balance event identity")
		}
		seen[r.ID] = true
		_, offset := e.OccurredAt.Zone()
		if e.OccurredAt.IsZero() || offset != 0 || !e.OccurredAt.Equal(r.OccurredAt) || e.OccurredAt.Before(window.Earliest) || e.OccurredAt.After(window.Latest) {
			return fmt.Errorf("balance event time")
		}
		w, ok := expected[key(e.Data)]
		if !ok || e.Data != w {
			return fmt.Errorf("balance payload differs from declared movement: got %+v want %+v", e.Data, w)
		}
		delete(expected, key(e.Data))
	}
	return nil
}

internal/transport/httpapi/dto.go:
package httpapi

import (
	"fmt"
	"time"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/domain/money"
)

// ---- Contracts (see api/openapi.yaml) -------------------------------------

type MoneyDTO struct {
	Amount   string `json:"amount"`
	Currency string `json:"currency"`
}

func toMoneyDTO(m money.Money) MoneyDTO { return MoneyDTO{m.Amount(), m.Currency()} }

func toMoneyDTOPtr(m *money.Money) *MoneyDTO {
	if m == nil {
		return nil
	}
	d := toMoneyDTO(*m)
	return &d
}

func (d MoneyDTO) parse() (money.Money, error) {
	m, err := money.Parse(d.Amount, d.Currency)
	if err != nil {
		return money.Money{}, fmt.Errorf("%w: %v", apperr.ErrInvalidInput, err)
	}
	return m, nil
}

type OpenWalletRequest struct {
	PlayerID       string   `json:"playerId"`
	InitialBalance MoneyDTO `json:"initialBalance"`
}

type WalletResponse struct {
	ID       string   `json:"id"`
	PlayerID string   `json:"playerId"`
	Balance  MoneyDTO `json:"balance"`
	Version  int64    `json:"version"`
}

type SubmitTransactionRequest struct {
	BetID                          string   `json:"betId,omitempty"`
	ProviderID                     string   `json:"providerId"`
	ExternalTransactionID          string   `json:"externalTransactionId"`
	PlayerID                       string   `json:"playerId"`
	WalletID                       string   `json:"walletId"`
	RoundID                        string   `json:"roundId"`
	GameID                         string   `json:"gameId"`
	Kind                           string   `json:"kind"`
	Money                          MoneyDTO `json:"money"`
	ReferenceExternalTransactionID string   `json:"referenceExternalTransactionId,omitempty"`
}

type SubmitTransactionResponse struct {
	TransactionID    string    `json:"transactionId"`
	Status           string    `json:"status"`
	Balance          *MoneyDTO `json:"balance,omitempty"`
	FailureCode      string    `json:"failureCode,omitempty"`
	IdempotentReplay bool      `json:"idempotentReplay"`
}

type TransactionResponse struct {
	TransactionID         string     `json:"transactionId"`
	ProviderID            string     `json:"providerId,omitempty"`
	ExternalTransactionID string     `json:"externalTransactionId,omitempty"`
	WalletID              string     `json:"walletId"`
	Kind                  string     `json:"kind"`
	Status                string     `json:"status"`
	Money                 MoneyDTO   `json:"money"`
	Balance               *MoneyDTO  `json:"balance,omitempty"`
	FailureCode           string     `json:"failureCode,omitempty"`
	NextAttemptAt         *time.Time `json:"nextAttemptAt,omitempty"`
}

type LedgerEntryDTO struct {
	WalletID      string    `json:"walletId"`
	ID            string    `json:"id"`
	TransactionID string    `json:"transactionId"`
	Direction     string    `json:"direction"`
	Money         MoneyDTO  `json:"money"`
	BalanceBefore MoneyDTO  `json:"balanceBefore"`
	BalanceAfter  MoneyDTO  `json:"balanceAfter"`
	CreatedAt     time.Time `json:"createdAt"`
}

type LedgerResponse struct {
	Entries    []LedgerEntryDTO `json:"entries"`
	NextCursor string           `json:"nextCursor,omitempty"`
}

type ReconciliationResponse struct {
	WalletID          string   `json:"walletId"`
	StoredBalance     MoneyDTO `json:"storedBalance"`
	CalculatedBalance MoneyDTO `json:"calculatedBalance"`
	Difference        MoneyDTO `json:"difference"`
	Consistent        bool     `json:"consistent"`
	CheckedEntries    int64    `json:"checkedEntries"`
}

type ErrorResponse struct {
	Code    string `json:"code"`
	Message string `json:"message,omitempty"`
}

internal/transport/httpapi/errors.go:
package httpapi

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/domain/settlement"
	"github.com/alexandre/wagering/internal/domain/wager"
)

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// writeError maps application errors to distinguishable HTTP contracts:
//
//	400 INVALID_INPUT · 403 FORBIDDEN · 404 NOT_FOUND · 409 IDEMPOTENCY_CONFLICT/WALLET_EXISTS
//	503 UNAVAILABLE (+Retry-After) · 500 INTERNAL
//
// (422 REJECTED and 202 PENDING are produced by the submit handler from the persisted result.)
func writeError(w http.ResponseWriter, err error) {
	code, domainFailure := wager.CodeOf(err)
	switch {
	case errors.Is(err, settlement.ErrReversalState):
		writeJSON(w, http.StatusConflict, ErrorResponse{"SETTLEMENT_NOT_PROCESSED", err.Error()})
	case domainFailure:
		writeJSON(w, http.StatusUnprocessableEntity, ErrorResponse{string(code), err.Error()})
	case errors.Is(err, settlement.ErrDistribution):
		writeJSON(w, http.StatusUnprocessableEntity, ErrorResponse{"INVALID_DISTRIBUTION", err.Error()})
	case errors.Is(err, apperr.ErrInvalidInput):
		writeJSON(w, http.StatusBadRequest, ErrorResponse{"INVALID_INPUT", err.Error()})
	case errors.Is(err, apperr.ErrForbidden):
		writeJSON(w, http.StatusForbidden, ErrorResponse{"FORBIDDEN", ""})
	case errors.Is(err, apperr.ErrNotFound), errors.Is(err, apperr.ErrWalletNotFound):
		writeJSON(w, http.StatusNotFound, ErrorResponse{"NOT_FOUND", ""})
	case errors.Is(err, apperr.ErrIdempotencyConflict):
		writeJSON(w, http.StatusConflict, ErrorResponse{"IDEMPOTENCY_CONFLICT", err.Error()})
	case errors.Is(err, apperr.ErrWalletExists):
		writeJSON(w, http.StatusConflict, ErrorResponse{"WALLET_EXISTS", err.Error()})
	case apperr.IsTransient(err):
		w.Header().Set("Retry-After", "1")
		writeJSON(w, http.StatusServiceUnavailable, ErrorResponse{"UNAVAILABLE", "temporary failure, retry with the same Idempotency-Key"})
	default:
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{"INTERNAL", ""})
	}
}

internal/transport/httpapi/handlers.go:
package httpapi

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"strconv"
	"time"

	"github.com/google/uuid"

	"github.com/alexandre/wagering/internal/app/apperr"
	"github.com/alexandre/wagering/internal/app/usecase"
	"github.com/alexandre/wagering/internal/domain/wager"
	"github.com/alexandre/wagering/internal/infra/auth"
)

type handlers struct{ d Deps }

type corrKey struct{}

func correlationID(ctx context.Context) string { s, _ := ctx.Value(corrKey{}).(string); return s }

// withCorrelation propagates/creates X-Correlation-Id (logs, events and responses share it).
func withCorrelation(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Correlation-Id")
		if id == "" {
			id = uuid.NewString()
		}
		w.Header().Set("X-Correlation-Id", id)
		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		defer cancel()
		next.ServeHTTP(w, r.WithContext(context.WithValue(ctx, corrKey{}, id)))
	})
}

func decode(w http.ResponseWriter, r *http.Request, v any) error {
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	var body json.RawMessage
	if err := dec.Decode(&body); err != nil {
		return apperr.Invalid("malformed body: %v", err)
	}
	// All request contracts require an object. encoding/json otherwise accepts
	// null into a struct and leaves its fields empty, confusing syntax with auth.
	if len(body) == 0 || body[0] != '{' {
		return apperr.Invalid("body must be a JSON object")
	}
	if dec.Decode(new(any)) != io.EOF {
		return apperr.Invalid("trailing JSON")
	}
	fields := json.NewDecoder(bytes.NewReader(body))
	fields.DisallowUnknownFields()
	fields.UseNumber()
	if err := fields.Decode(v); err != nil {
		return apperr.Invalid("malformed body: %v", err)
	}
	return nil
}

func (h handlers) openWallet(w http.ResponseWriter, r *http.Request) {
	var req OpenWalletRequest
	if err := decode(w, r, &req); err != nil {
		writeError(w, err)
		return
	}
	m, err := req.InitialBalance.parse()
	if err != nil {
		writeError(w, err)
		return
	}
	v, err := h.d.OpenWallet.Execute(r.Context(), usecase.OpenWalletInput{PlayerID: req.PlayerID, InitialBalance: m})
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, WalletResponse{v.ID, v.PlayerID, toMoneyDTO(v.Balance), v.Version})
}

func (h handlers) getWallet(w http.ResponseWriter, r *http.Request) {
	v, err := h.d.GetWallet.Execute(r.Context(), r.PathValue("walletId"))
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, WalletResponse{v.ID, v.PlayerID, toMoneyDTO(v.Balance), v.Version})
}

func (h handlers) listLedger(w http.ResponseWriter, r *http.Request) {
	limit := 50
	if s := r.URL.Query().Get("limit"); s != "" {
		n, err := strconv.Atoi(s)
		if err != nil || n < 1 || n > 200 {
			writeError(w, apperr.Invalid("limit must be between 1 and 200"))
			return
		}
		limit = n
	}
	page, err := h.d.ListLedger.Execute(r.Context(), r.PathValue("walletId"), r.URL.Query().Get("cursor"), limit)
	if err != nil {
		writeError(w, err)
		return
	}
	out := LedgerResponse{Entries: make([]LedgerEntryDTO, 0, len(page.Entries)), NextCursor: page.NextCursor}
	for _, e := range page.Entries {
		out.Entries = append(out.Entries, LedgerEntryDTO{e.WalletID(), e.ID(), e.TransactionID(), string(e.Direction()),
			toMoneyDTO(e.Amount()), toMoneyDTO(e.BalanceBefore()), toMoneyDTO(e.BalanceAfter()), e.CreatedAt().UTC()})
	}
	writeJSON(w, http.StatusOK, out)
}

func (h handlers) reconcile(w http.ResponseWriter, r *http.Request) {
	res, err := h.d.Reconcile.Execute(r.Context(), r.PathValue("walletId"))
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, ReconciliationResponse{res.WalletID, toMoneyDTO(res.Stored), toMoneyDTO(res.Calculated),
		toMoneyDTO(res.Difference), res.Consistent, res.CheckedEntries})
}

func (h handlers) submit(w http.ResponseWriter, r *http.Request) {
	key := r.Header.Get("Idempotency-Key")
	if key == "" {
		writeError(w, apperr.Invalid("Idempotency-Key header is required"))
		return
	}
	var req SubmitTransactionRequest
	if err := decode(w, r, &req); err != nil {
		writeError(w, err)
		return
	}
	p, _ := auth.PrincipalFrom(r.Context())
	res, err := h.d.Submit.Execute(r.Context(), usecase.SubmitInput{
		Source: usecase.SourceHTTP, AuthorizedProviderID: p.ProviderID, IdempotencyKey: key,
		CorrelationID: correlationID(r.Context()),
		BetID:         req.BetID,
		ProviderID:    req.ProviderID, ExternalTransactionID: req.ExternalTransactionID, PlayerID: req.PlayerID,
		WalletID: req.WalletID, RoundID: req.RoundID, GameID: req.GameID, Kind: req.Kind,
		ReferenceExternalTransactionID: req.ReferenceExternalTransactionID,
		Amount:                         req.Money.Amount, Currency: req.Money.Currency,
	})
	if err != nil {
		writeError(w, err)
		return
	}
	body := SubmitTransactionResponse{res.TransactionID, string(res.Status), toMoneyDTOPtr(res.Balance),
		string(res.FailureCode), res.IdempotentReplay}
	switch res.Status {
	case wager.StatusProcessed:
		writeJSON(w, http.StatusOK, body)
	case wager.StatusRejected, wager.StatusFailed:
		writeJSON(w, http.StatusUnprocessableEntity, body) // definitive business outcome
	default: // PENDING / PENDING_REFERENCE
		w.Header().Set("Location", "/wagering/transactions/"+res.TransactionID)
		writeJSON(w, http.StatusAccepted, body)
	}
}

func scopeOf(r *http.Request) usecase.Scope {
	p, _ := auth.PrincipalFrom(r.Context())
	return usecase.Scope{ProviderID: p.ProviderID, Internal: p.Internal}
}

func toTxResponse(v usecase.TransactionView) TransactionResponse {
	return TransactionResponse{v.ID, v.ProviderID, v.ExternalTransactionID, v.WalletID, string(v.Kind), string(v.Status),
		toMoneyDTO(v.Amount), toMoneyDTOPtr(v.Balance), string(v.FailureCode), v.NextAttemptAt}
}

func (h handlers) getTransaction(w http.ResponseWriter, r *http.Request) {
	v, err := h.d.GetTx.ByID(r.Context(), r.PathValue("transactionId"), scopeOf(r))
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, toTxResponse(v))
}

func (h handlers) getProviderTransaction(w http.ResponseWriter, r *http.Request) {
	v, err := h.d.GetTx.ByExternalID(r.Context(), r.PathValue("providerId"), r.PathValue("externalTransactionId"), scopeOf(r))
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, toTxResponse(v))
}

internal/transport/httpapi/module.go:
package httpapi

import (
	"context"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"time"

	"go.uber.org/fx"

	"github.com/alexandre/wagering/internal/app/port"
	"github.com/alexandre/wagering/internal/app/usecase"
	"github.com/alexandre/wagering/internal/infra/auth"
	"github.com/alexandre/wagering/internal/infra/config"
	"github.com/alexandre/wagering/internal/platform/metrics"
	"github.com/alexandre/wagering/internal/platform/worker"
)

var Module = fx.Module("httpapi", fx.Provide(NewServer), fx.Invoke(func(*http.Server) {}))

type Deps struct {
	fx.In
	OpenWallet *usecase.OpenWallet
	GetWallet  *usecase.GetWallet
	ListLedger *usecase.ListLedger
	Reconcile  *usecase.ReconcileWallet
	Submit     *usecase.SubmitTransaction
	GetTx      *usecase.GetTransaction
	Auth       *auth.Verifier
	Metrics    *metrics.Recorder
	Checks     []port.ReadinessChecker `group:"readiness"`
}

func chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

func NewServer(lc fx.Lifecycle, group *worker.Group, cfg config.Config, log *slog.Logger, d Deps) *http.Server {
	h := handlers{d}
	mux := http.NewServeMux()

	// ---- Public --------------------------------------------------------------
	mux.HandleFunc("GET /health/live", func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) })
	mux.HandleFunc("GET /health/ready", func(w http.ResponseWriter, r *http.Request) {
		for _, c := range d.Checks {
			ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
			err := c.Check(ctx)
			cancel()
			if err != nil {
				log.Warn("not ready", "check", c.Name(), "err", err)
				writeJSON(w, http.StatusServiceUnavailable, ErrorResponse{"NOT_READY", c.Name()})
				return
			}
		}
		w.WriteHeader(http.StatusOK)
	})
	mux.Handle("GET /metrics", d.Metrics.Handler())

	// ---- Internal service only (client_credentials, role=internal) -----------
	internal := func(f http.HandlerFunc) http.Handler {
		return chain(f, d.Auth.Authenticate, auth.RequireInternal)
	}
	mux.Handle("GET /settlements/{settlementId}", internal(h.getSettlement))
	mux.Handle("POST /settlements/{settlementId}/rollback", internal(h.reverseSettlement))
	mux.Handle("POST /bets", internal(h.createBet))
	mux.Handle("POST /bets/{betId}/result", internal(h.confirmResult))
	mux.Handle("POST /wallets", internal(h.openWallet))
	mux.Handle("GET /wallets/{walletId}", internal(h.getWallet))
	mux.Handle("GET /wallets/{walletId}/ledger", internal(h.listLedger))
	mux.Handle("POST /wallets/{walletId}/reconciliation", internal(h.reconcile))

	// ---- Providers (providerId derived from the token) -----------------------
	mux.Handle("POST /wagering/transactions", chain(http.HandlerFunc(h.submit), d.Auth.Authenticate, auth.RequireProvider))
	either := func(f http.HandlerFunc) http.Handler {
		return chain(f, d.Auth.Authenticate, auth.RequireProviderOrInternal)
	}
	mux.Handle("GET /wagering/transactions/{transactionId}", either(h.getTransaction))
	mux.Handle("GET /providers/{providerId}/wagering/transactions/{externalTransactionId}", either(h.getProviderTransaction))

	srv := &http.Server{ErrorLog: slog.NewLogLogger(log.Handler(), slog.LevelError), Addr: cfg.HTTPAddr, Handler: withCorrelation(mux), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 15 * time.Second, WriteTimeout: 15 * time.Second, IdleTimeout: 60 * time.Second}
	var listener net.Listener
	if cfg.HasRole("api") {
		worker.Register(group, "http", log, func(context.Context) error {
			err := srv.Serve(listener)
			if errors.Is(err, http.ErrServerClosed) {
				return nil
			}
			return err
		})
		group.Drain(func(ctx context.Context) error { return shutdownServer(ctx, srv) })
	}
	lc.Append(fx.Hook{
		OnStart: func(context.Context) error {
			if !cfg.HasRole("api") {
				return nil
			}
			ln, err := net.Listen("tcp", srv.Addr)
			if err != nil {
				return err
			}
			listener = ln
			return nil
		},
		// Also closes a listener if a later startup hook fails before Group starts.
		OnStop: func(context.Context) error {
			if listener != nil {
				_ = listener.Close()
			}
			return srv.Close()
		},
	})
	return srv
}

func shutdownServer(ctx context.Context, srv *http.Server) error {
	err := srv.Shutdown(ctx)
	if err != nil {
		_ = srv.Close()
	}
	return err
}

